quests[29710] = { id = 29710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Geplünderte Lebensmittelkiste" }
quests[29711] = { id = 29711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Geplünderte Schriftolle" }
quests[29712] = { id = 29712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hordenjustiz", description = "Euer Verstand arbeitet fieberhaft, während Ihr versucht Eure unselige Lage einzuschätzen – gestrandet in einem unbekannten Land, fast die gesamte Mannschaft verloren...\n\nAls Ihr den Leichnam dieser unglücklichen Kreatur betrachtet, wird Euch klar, dass die Gegend voll mit diesen Wesen ist und sie alle Vorräte plündern, die nicht zerstört worden sind.\n\nEs wird Zeit, diesen Maden zu zeigen, was die Horde unter Gerechtigkeit versteht.", sourceObjective = "Tötet 15 Ho-zen am Wrack der Himmelshai.", sourceObjectiveStatus = "unverified-source-field" }
quests[29713] = { id = 29713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standardverfahren", description = "Die Himmelshai ist vollständig zerstört worden.\n\nDa sich Allianztruppen in der Gegend befinden, sieht das Standardverfahren vor, alle kritischen Technologien zu zerstören. Und die Solenoiden fallen ganz sicher in diese Kategorie.\n\nDie Anweisungen der Horde sind klar - die Solenoiden zur Vernichtung zusammentragen.", sourceObjective = "Tragt 8 instabile Solenoiden zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29714] = { id = 29714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nasse Sache!", description = "Falls irgendwelche Seestreitkräfte der Allianz an Land gekommen sind, werden die Rauchwolken sie nach dem Absturz direkt zu Euch und Euren verbliebenen Leuten führen.\n\nEs muss doch möglich sein, das Feuer zu löschen...\n\nDieses Fass scheint die Katastrophe heil überstanden zu haben. Möglicherweise ist es noch wasserdicht.\n\nEs gibt nur einen Weg, das herauszufinden!", sourceObjective = "Sammelt 5 Wasserkugeln aus dem Geisterliedsee und kombiniert sie mit dem Hordefass.", sourceObjectiveStatus = "unverified-source-field" }
quests[29715] = { id = 29715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hexe im Wald", description = "Oh bitte, {race}! Könnt Ihr mir helfen?\n\nEinige der Dorfkinder haben im Wald gespielt und sind nicht zurückgekehrt. Könntet Ihr bitte nach ihnen Ausschau halten, wenn Ihr dort hingeht?\n\nIch habe diesen Dorfrackern ausdrücklich gesagt, sie sollen die alte Witwe dort im Wald in Ruhe lassen. Ich vermute, dass sie sie wahrscheinlich belästigen. Sie glauben, dass sie eine Hexe ist.", sourceObjective = "Findet An Windpelz an der Straße nördlich der Hütte der Jadehexe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29716] = { id = 29716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die doppelte Ho-zen-Mutprobe", description = "In den Wäldern gibt es eine Hexe, aber niemand glaubt mir. Sie hat meinen Freund Shin in Jade verwandelt!\n\nWir hatten alle solche Angst und versuchten, nach Hause zu rennen, aber sie hat ihre großen Jademonster hinter uns hergeschickt. Ein paar von meinen Freunden versuchten, ihnen zu entkommen, indem sie auf Bäume kletterten.\n\nKönnt Ihr mir helfen, meine Freunde zu retten?", sourceObjective = "Rettet 6 verängstigte Pandarenkinder.", progress = "Wo ist Shin? Ich habe Shin nicht gesehen.", completion = "Oh, vielen Dank, dass Ihr geholfen habt, meine Freunde zu finden. Ich sehe Shin aber immer noch nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[29717] = { id = 29717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braves Kätzchen!", description = "Ich habe versucht, einen der Jadetiger in den Wäldern zu bekämpfen, aber ich hatte zu viel Angst. Wenn sie einen anstarren, verwandelt man sich in eine Jadestatue!\n\nWirklich wahr! Ni, die Freundin von Chens Schwester, hat es von Kais Mutter erfahren.\n\nIch möchte auch so mutig sein wie Ihr. Könnt Ihr mir zeigen, wie man diese Jadetiger bekämpft?", sourceObjective = "Vernichtet 8 Jadewächter.", completion = "Das war ja unglaublich! Ihr habt denen so *WUMM* eine reingehauen und die nur so *AAHHH* und schon waren die hin!", sourceObjectiveStatus = "unverified-source-field" }
quests[29718] = { id = 29718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein halber Liter Schutz", description = "Vorsicht ist besser als Nachsicht.\n\nDie Rauchsäulen an der Absturzstelle zeigt jedem Allianzler, der die Probleme Eures Zeppelins gesehen hat, wo er hinmuss.\n\nBis Ihr und Eure erschöpfte Mannschaft Euch aufgerappelt habt, solltet Ihr solche Konfrontationen besser vermeiden.\n\nLöscht das Feuer am Wrack, das ist die beste Vorgehensweise.", sourceObjective = "Nutzt das Geist-berührte Wasserfass, um die vier Feuer in der Nähe des Zeppelinwracks zu löschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29719] = { id = 29719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die doppelte Ho-zen-Mutprobe", description = "Shin ist immer noch verschwunden!\n\nIch hätte... Ich meine, die anderen Kinder hätten ihn niemals auf die doppelte Ho-zen-Mutprobe stellen und an die Tür der Hexe klopfen lassen sollen.\n\nWir haben einen ganzen Haufe Jadestatuen im Garten der Jadehexe gesehen.\n\nKönntet Ihr mich begleiten, um herauszufinden, ob eine davon Shin ist?", sourceObjective = "Untersucht 7 lebensechte Jadestatuen südlich der Hütte der Jadehexe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29720] = { id = 29720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jadehexe", description = "Ich glaube, die Jadehexe hält Shin immer noch gefangen.\n\nAber ich... Ich kann das nicht! Ich trau' mich nicht, zu der Hexe zu gehen. Könntet Ihr vielleicht mit ihr sprechen? Ihr seid doch schon erwachsen. Ich glaube, Euch würde sie nicht in Jade verwandeln.", sourceObjective = "Sprecht mit Witwe Grünpfote bei der Hütte der Jadehexe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29721] = { id = 29721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallen gegen Gefallen", description = "Nun, <junger Abenteurer/junge Abenteurerin>, ich möchte Euch um einen Gefallen bitten, bevor ich Euch helfe.\n\nHinter meiner Hütte befindet sich ein kleiner Teich. Dort halte ich ein paar sehr seltene Fische, die ich für ein Ritual benötige. Das ware eine der Lieblingsbeschäftigungen meines verstorbenen Mannes.\n\nKönntet Ihr mir bitte einen von ihnen bringen?", sourceObjective = "Witwe Grünpfote hat Euch gebeten, ihr einen Fisch aus dem Teich hinter der Hütte der Jadehexe im Jadewald zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29722] = { id = 29722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Sachen Mut", description = "Könntet Ihr mir beibringen, auch so tapfer zu sein wie Ihr?\n\nAls wir der Hexe einen Streich gespielt haben, haben wir ein paar blättrige Trickster verärgert. Ich glaube, die Hexe hat irgendetwas mit ihnen angestellt.\n\nKönntet Ihr mir zeigen, wie man gegen die ankommt?", sourceObjective = "Besiegt 8 blättrige Trickster südlich der Hütte der Jadehexe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29723] = { id = 29723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jadehexe", description = "Ich glaube, die Jadehexe hält Shin immer noch gefangen.\n\nAber ich... Ich kann das nicht! Ich trau' mich nicht, zu der Hexe zu gehen. Könntet Ihr vielleicht mit ihr sprechen und nachsehen, ob sie Shin immer noch gefangen hält? Ihr seid doch schon erwachsen. Ich glaube, Euch würde sie nicht in Jade verwandeln.", sourceObjective = "Besiegt die Jadehexe.", completion = "Hurra! Ich danke Euch! Shin ist gerettet und Ihr habt die alte Hexe besiegt! Und das Beste ist, dass unsere Eltern nie erfahren werden, was wir gemacht haben. Hurra!\n\nIrgendwie scheinen alle, die zurückgekommen sind, zu versuchen, ihre ganze Jade loszuwerden. Toya hat alles gesammelt und gesagt, dass Ihr mit ihm sprechen sollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29724] = { id = 29724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seebestattung", description = "Diese Wilden sind... unbarmherzig.\n\nSie haben unsere sterbenden Soldaten verschleppt, um sie in ihren Lagern zu foltern. So dürfen unsere tapferen Brüder und Schwestern nicht sterben.\n\nSchon bald werde ich einer von ihnen sein, {class}. Bitte, verschafft sowohl meinem Geist als auch ihren Körpern Ruhe.\n\nFindet ihre sterblichen Überreste in den Lagern, die das Wrack umgeben. Bringt sie außer Reichweite dieser Kreaturen.", sourceObjective = "Bringt die 3 Leichen der Vorhut zum stationären Katapult am Wrack der Himmelshai.", sourceObjectiveStatus = "unverified-source-field" }
quests[29725] = { id = 29725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Bericht: Feuer vom Himmel", description = "Ja, wir haben Amber gefunden und sie ist am Leben und so. Aber das sind auch schon die einzigen guten Nachrichten.\n\nIch versuche mal, da weiterzumachen, wo der gute alte Rell aufhören musste...", sourceObjective = "Hört Euch Sullys Bericht an.", completion = "So, jetzt wisst Ihr, was mit dem guten alten Rell passiert ist.\n\n<Ihr bemerkt eine Änderung in Sullys Mimik und er wendet sich plötzlich ab. Ist es möglich, dass er... weint?>", sourceObjectiveStatus = "unverified-source-field" }
quests[29726] = { id = 29726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Bericht: Feindliche Eingeborene", description = "Ich... Ich kann Euch sagen, was als Nächstes passiert ist! Wir waren auf dem Weg nach Norden, in den Wald...", sourceObjective = "Hört Euch Klein-Lus Bericht an.", completion = "Glücklicherweise haben wir alle überlebt.\n\nNa ja... bis auf Söckchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[29727] = { id = 29727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Bericht: Keine Gefangenen", description = "Die letzte Etappe unserer Reise brachte uns in den Westen, wo es ein großes Ho-zen-Dorf gibt. Wir hatten ein kleines Lager aufgeschlagen, außerhalb ihrer Sichtweite...", sourceObjective = "Hört Euch Amber Kearnens Bericht an.", completion = "Und so war's. Wir konnten den Weißen Bauern nicht finden, aber wir haben Geheiminformationen erhalten, die für die Allianz vielleicht noch viel wichtiger sind.\n\nDie Horde hat sich mit den Ho-zen verbündet und stattet sie aktuell gerade mit Waffen aus. Zusammen mit ihrer Affenarmee sind sie uns gegenüber dreißigfach in der Überzahl.", sourceObjectiveStatus = "unverified-source-field" }
quests[29728] = { id = 29728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweismittelvernichtung", description = "Ich muss Euch um einen weiteren Einsatz bitten, {name}.\n\nWir dürfen nicht zulassen, dass die persönlichen Dinge auf diesem Schiff in die falschen Hände fallen. Wir müssen es zerstören.\n\nAus den Überresten, die Ihr mir gebracht habt, habe ich ein paar improvisierte Sprengladungen zusammengestellt.\n\nBitte platziert diese Ladungen an einer beliebigen Stelle am Schiff. Aber achtet darauf, sie nicht zu dicht zusammenzulegen.\n\nSie sind ein wenig... öh... instabil. Im Falle einer vorzeitigen Explosion sollten sie also besser etwas verteilt sein.", sourceObjective = "Platziert 4 improvisierte Sprengladungen in der Nähe des Wracks der Herold. Die improvisierten Sprengladungen müssen mindestens 10 Meter voneinander entfernt liegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29729] = { id = 29729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spurlos verschwunden", description = "Die Sprengladungen sind platziert. Jetzt müssen wir nur noch den Auslöser betätigen.", sourceObjective = "Drückt den Auslöser, um die verbleibenden Beweismittel zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29730] = { id = 29730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherbericht: Feindliche Eingeborene", description = "Ich glaub', ich kenne Eure erste Frage: \"Was zum Fiddel ist mit Unteroffizier Gorrok passiert?\" Aber keine Sorge. Der ist total am Leben. Gar nicht tot oder so.\n\n<Riko rutscht nervös hin und her.>\n\nAlso, wir GLAUBEN zumindest, dass er lebt. Aber er KÖNNTE AUCH ganz schön tot sein.\n\n<Riko schaut Euch erwartungsvoll an.>\n\nAlso gut! Ich werde Euch genau erzählen, was passiert ist.", sourceObjective = "Hört Euch Rikos Bericht an.", completion = "So, wie Ihr also seht, trifft Riko keine Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[29731] = { id = 29731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherbericht: Auf der richtigen Fährte", description = "Das MEISTE, von dem, was Riko erzählt hat, ist wahr.\n\nWir haben uns nicht getraut, Gorrok zu verfolgen - die Horde verfügt nicht über ausreichend Truppen. Wir können auch nur eine bestimmte Anzahl Verluste kompensieren und ehrlich gesagt weiß ich nicht, wie mächtig diese Hexe ist.\n\nIch erzähle von da weiter, wo der Ho-zen aufgehört hat...", sourceObjective = "Hört Euch Kiryns Bericht an.", completion = "Und so haben wir unseren Allianzgefangenen gefunden.\n\nAber es ist noch viel mehr passiert. Noch sehr viel mehr...", sourceObjectiveStatus = "unverified-source-field" }
quests[29732] = { id = 29732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was runtergeht, muss wieder rauf!", description = "Nieti hat etwas hinterlassen, was sehr wichtig zu sein scheint. Auf dem Schaft steht \"Goblindrohnenspender\".\n\nNach einer kleinen Kalibrierung kann das Gerät Drohnen ins Basislager von Nazgrim entsenden.\n\nSo weit, so gut...\n\nEs gibt nur ein Problem: Die einzigen Vorratskisten, die einen Transport wert wären, sind nach dem Aufprall von der Klippe gefallen.\n\nAls Ihr darüber nachdenkt, seht Ihr im Augenwinkel den langen, zusammengerollten Schwanz eines vorbeifliegenden Klippengleiters...", sourceObjective = "Benutzt den Goblindrohnenspender an der Freigelegten Wurzel, um Vorräte zu bergen.\n\nHINWEIS: Für jede Benutzung ist ein Klippengleiterschwanz erforderlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[29733] = { id = 29733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Bericht: Verloren im Wald", description = "<Rell hustet schwer, bevor er spricht.>\n\nIch bitte Euch, {name}. Ihr müsst Euch anhören, was wir durchgemacht haben.\n\nDie gesamte verdammte Allianz sollte sich anhören, was wir durchgemacht haben. Es bleibt vielleicht nicht mehr viel Zeit.", sourceObjective = "Hört Euch Rells Bericht an.", completion = "...und so <hust> fanden wir...\n\n<Rells Erzählung wird von einem Hustenanfall unterbrochen. Blut läuft ihm aus einem Mundwinkel.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29734] = { id = 29734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Tiefenschmiede", sourceObjective = "Ich spüre das Feuer des Lebens in Euch, {class}. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[29735] = { id = 29735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Steinsiegel", sourceObjective = "Ich spüre das Feuer des Lebens in Euch, {class}. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[29736] = { id = 29736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Dunkelfeder", sourceObjective = "Euer Geist steckt voller Leben, junger {class}. Ich freue mich über den Respekt, den Ihr mir zollt, und gebe Euch dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29737] = { id = 29737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Feuerbart", sourceObjective = "Ich spüre das Feuer des Lebens in Euch, {class}. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[29738] = { id = 29738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Mondlanze", sourceObjective = "Der Himmel, mit seinen unzähligen Sternen, bietet die Antworten auf alle irdenen Fragen, {name}. Mag es sein, dass wenn der Weise und Glückliche zu ihnen aufblickt, er die tiefere Wahrheit findet?", sourceObjectiveStatus = "unverified-source-field" }
quests[29739] = { id = 29739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahnin Windsang", sourceObjective = "Der Himmel, mit seinen unzähligen Sternen, bietet die Antworten auf alle irdenen Fragen, {name}. Mag es sein, dass wenn der Weise und Glückliche zu ihnen aufblickt, er die tiefere Wahrheit findet?", sourceObjectiveStatus = "unverified-source-field" }
quests[29740] = { id = 29740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahnin Immerschatten", sourceObjective = "Im endlosen Glitzern der Sterne verbergen sich die Antworten auf alle irdischen Mysterien, {name}. Darf man dann nicht annehmen, dass der Weise und der Glückspilz beim Blick nach oben die Wahrheit entdecken könnten?", sourceObjectiveStatus = "unverified-source-field" }
quests[29741] = { id = 29741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Sekhemi", sourceObjective = "Alle Tol'vir waren einst wie ich. Nun besteht mein Volk aus Fleisch und Blut und benötigt die Weisheit der Zeitalter mehr als je zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[29742] = { id = 29742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Menkhaf", sourceObjective = "Alle Tol'vir waren einst wie ich. Nun ist mein Volk aus Fleisch und Blut und braucht die Weisheit der Zeitalter dringender als je zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[29743] = { id = 29743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missgestalt", description = "Die Statue und die sie umgebenden Ruinen sind eindeutig uralt. Dieses Land besitzt offenbar eine tiefgründige Geschichte. Das bedeutet, dass es nicht aus dem Kataklysmus entsprungen sein kann.\n\nDoch obwohl diese Gewässer nunmehr seit Ewigkeiten erforscht wurden, gibt es kein Anzeichen für etwas anderes als offene See.\n\nWenn Ihr die Einzelteile dieser zerbrochenen Statue zeichnen würdet, könntet Ihr vielleicht ein wenig Licht auf die Ursprünge dieses Kontinents werfen.", sourceObjective = "Erstellt Zeichnungen von jedem Einzelteil der antiken Statue.", sourceObjectiveStatus = "unverified-source-field" }
quests[29744] = { id = 29744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naturschutz", description = "Waldgeister sind nicht für ihre Wanderlust bekannt, deswegen wundert es mich, dass sie sich bis zum Steinmetzviertel vorgewagt haben. Irgendetwas muss sie aus ihrem normalen Lebensraum vertreiben.\n\nDiese Geister leben eigentlich in den Wäldern der Verlorenen, gleich nördlich von hier. Ich würde ja selbst dorthin gehen, aber ich hörte, dass die Wälder verwunschen sein sollen.\n\nDas ist dann also nicht mehr drin.\n\nWir werden es wohl nie erfahren.\n\n<Weng hustet.>\n\nEs sei denn... es findet sich für diese Aufgabe <ein großer starker Abenteurer/eine große starke Abenteurerin> wie IHR! Was sagt Ihr dazu?", sourceObjective = "Untersucht die Wälder der Verlorenen, nordöstlich des Grünsteinbruchs.", sourceObjectiveStatus = "unverified-source-field" }
quests[29745] = { id = 29745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Misere der Geister", description = "<Lebende Statuen wüten in den Wäldern.\n\nBis jetzt scheinen sie sich damit zufrieden zu geben, die Waldgeister in Stücke zu hauen, aber wenn sie so weitermachen, haben die Pandaren bald andere Sorgen als nur die verschwundene Jade.>", sourceObjective = "Schaltet 10 steingebundene Zerstörer in den Wäldern der Verlorenen aus und offenbart ihre Quelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[29746] = { id = 29746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer den Geistern nach", description = "Die aus den Statuen befreiten Geister werden, offensichtlich gewaltsam, in Richtung der Küstenruinen dort oben gezogen.\n\nEs scheint unwahrscheinlich, dass sie dort Ruhe finden...", sourceObjective = "Begebt Euch in die Ruinen von Gan-Shi, nordwestlich der [JADEMINEN].", sourceObjectiveStatus = "unverified-source-field" }
quests[29747] = { id = 29747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Zyklus durchbrechen", description = "<Mogubeschwörer rufen die unglückseligen Geister aus der Unterwelt herauf und sperren sie in diese Statuen ein.\n\nAnscheinend reicht es nicht aus, die Statuen zu zerstören, um diesen Kreislauf zu unterbrechen.>", sourceObjective = "Tötet 8 Shan'ze-Geisterbinder auf der Terrasse der Zehn Donner.", sourceObjectiveStatus = "unverified-source-field" }
quests[29748] = { id = 29748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simulakrumwerfen", description = "<Die geborstenen Überreste einer uralten Mogustatue. Sie sieht aus, als ob sie auch vor ihrer Zerstörung nie von Leben erfüllt war.\n\nWelche dunkle Magie die Mogu auch immer hier verwenden, sie scheint die brüchigen Statuen deutlich robuster zu machen. Wir sollten sie besser zerstören, solange sie leer sind und wir die Gelegenheit dazu haben.\n\nEin guter alter Tritt sollte dazu ausreichen.>", sourceObjective = "Tretet 6 leere Zerstörer auf der Terrasse der Zehn Donner um.", sourceObjectiveStatus = "unverified-source-field" }
quests[29749] = { id = 29749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein dringendes Anliegen", description = "<Euer Verstand wird von einem Heulen erschüttert. Darunter vernehmt Ihr eine kaum wahrnehmbare Stimme, wie von weit her.>\n\nBitte... helft... inmitten der Ruinen... ein Ritual... beschwören...\n\n... sollte nicht hier sein...\n\nMein Stab... auf dem Altar... nehmt ihn. Bitte beeilt Euch.", sourceObjective = "Bergt den Stab von Pei-Zhi und unterbrecht das Beschwörungsritual der Mogu im Zentrum der Terrasse der Zehn Donner.", progress = "Geistbindung! Wie konnte es den Mogu gestattet werden, mit solch widerwärtigen Praktiken fortzufahren?! Und jetzt steh' ich hier: Das Produkt einer halb gescheiterten Beschwörung...\n\n<Der Geist zürnt noch ein wenig vor sich hin und wendet sich dann Euch zu.>\n\nIn welchem Jahrhundert befinden wir uns?", completion = "Gestatten, Pei-Zhi, meines Zeichens Meistergeistweiser unter dem letzten Pandaren-Kaiser Shaohao.\n\nZumindest... war ich das einmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29750] = { id = 29750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geistergefäße", description = "Die Geisterklauen sind eine Sekte von Moguassassinenpriestern, die zu den Hochzeiten des Mogureiches die gefürchtetste und hervorragendste Truppe des Reiches darstellten.\n\nAlle ihre Mitglieder vermochten, einen Todeshieb auszuführen, der den Geist des Feindes in eine Jadeflasche bannte, um ihn dann an einen Geisterbinder auszuliefern.\n\nWenn Ihr weiter oben in den Ruinen auf Geisterklauen stoßt, solltet Ihr Folgendes wissen: An ihren Gürteln sind die verfluchten Geistergefäße befestigt.\n\nBefreit sie von dieser Bürde und bringt die Flaschen zu mir zurück.", sourceObjective = "Sichert 8 Geisterflaschen von den Shan'ze-Geisterklauen auf der Terrasse der Zehn Donner.", progress = "Dass die Mogu über all diese Jahre weiter die Geisterklauen ausgebildet haben...\n\nHabt Ihr die Flaschen?", completion = "Ich danke Euch, {class}.\n\nIch kann bereits die Geister in diesen Flaschen spüren - ich höre ihre Schreie voller Angst, Verwirrung und... Zorn.", sourceObjectiveStatus = "unverified-source-field" }
quests[29751] = { id = 29751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritualartefakte", description = "So viele Geister werden hier in Gefangenschaft gehalten... Ich kann sie überall spüren. Selbst die Wände dienen als Käfig für die schon lange Verstorbenen.\n\n{name}, wir können den Zauber, der über diesem Ort liegt, nicht einfach brechen. Denn dann würden zahllose gepeinigte Seelen ziellos umher irren. Sie brauchen ein Signal - etwas, das sie leitet.\n\nMit Eurer Hilfe könnte ich einen Tan-Chao erstellen: eine Brücke von dieser Welt in den Himmel. Für dieses Ritual benötige ich eine Schale, eine Kerze und einen Jadecong. Ihr solltet all diese Dinge in den Ruinen finden können.", sourceObjective = "Bringt Pei-Zhi eine gesprungene Ritualschale, eine geruchsintensive Ritualkerze und einen Jadecong von der Terrasse der Zehn Donner.", progress = "Habt Ihr die Ritualgegenstände gefunden? Ohne sie können wir die Geister nicht zurückgeleiten.", completion = "Gut gemacht. Damit kann ich das Ritual abhalten und alle Geister hier, unter anderem mich selbst, dorthin zurückgeleiten, wo sie hingehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[29752] = { id = 29752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verirrten Seelen", description = "Der Vorgang der Massenbeschwörung, wie hier von den Mogu abgehalten, hat auch unerwünschte Nebeneffekte. Einige der Geister kommen zu verstört oder unruhig hier an, um sich leiten zu lassen. Dann werden sie erst einmal isoliert, bis ihre Verzweiflung sie leichter beeinflussbar macht.\n\nIch vermute, dass die Mogu irgendwo einen solchen Isolationsbereich angelegt haben, der wahrscheinlich von Geisterklauen bewacht wird.\n\nBitte nehmt noch einmal meinen Stab und verwendet ihn, um diese verlorenen Seelen einzusammeln. Ihr müsst sie nicht bekämpfen. Zeigt ihnen einfach den Stab - damit sollten sie sich einfangen lassen.", sourceObjective = "Verwendet den Stab von Pei-Zhi, um 10 verirrte Urahnen auf der Terrasse der Zehn Donner einzufangen.", completion = "Ich danke Euch, {name}. Ich werde sie mit mir in den Nether nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29753] = { id = 29753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zur Natur", description = "Ich muss Euch leider erneut um einen Gefallen bitten, {name}.\n\nDie von Euch sichergestellten Flaschen enthalten weder die Geister von Urahnen der Mogu noch jene ihrer jüngst bezwungenen Feinde, sondern vielmehr die Seelen von Tieren. Offensichtlich haben die Geisterklauen auf Wilderei zurückgegriffen, um ihre Simulakren zu erwecken.\n\nLeider macht dies unsere Aufgabe komplizierter, da ich Tiere nicht mit durch den Tan-Chao nehmen kann.\n\nBringt diese Flaschen nach Westen in das Gezeitenblickdickicht und zerschlagt sie, damit die Tiere in die Natur zurückkehren können. Einige werden ganz sicher so zornig sein, dass Ihr sie erst beruhigen müsst.", sourceObjective = "Befreit 8 Tiergeister, indem Ihr die Geisterflaschen im Gezeitenblickdickicht auf den Boden werft.", completion = "Ihre Körper sind schon vor langer Zeit in ihre Heimat zurückgekehrt - jetzt können ihre Seelen ihnen folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29754] = { id = 29754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Verbindung zwischen Erde und Himmel", description = "Wir sind jetzt bereit, den Tan-Chao zu öffnen und die Seelen ihrem Frieden zuzuführen.\n\nEs wäre sehr freundlich, wenn Ihr mir noch einmal helfen könntet. Die Mogu werden sicher das Ritual bemerken und alles tun, um es aufzuhalten. Ich benötige nur ein paar Momente ungestörter Konzentration. Dann wird der Weg so weit geöffnet sein, dass er nicht mehr geschlossen werden kann.\n\nWenn Ihr mir noch einmal helfen möchtet, begleitet mich bitte zur Ritualstätte.", sourceObjective = "Beschützt Pei-Zhi während seines Rituals auf der Terrasse der Zehn Donner.", sourceObjectiveStatus = "unverified-source-field" }
quests[29755] = { id = 29755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ende der Pei-n", description = "<Die Geister der Urahnen strömen in den Tan-Chao, Pei-Zhis Brücke in die Freiheit.\n\nEine letzte Kammer befindet sich in den Ruinen gleich nördlich des Tan-Chao. Die Luft darüber vibriert vor schändlicher Energie. Shan Jitong hat sein Werk bereits begonnen.>", sourceObjective = "Bekämpft Shan Jitong und rettet Pei-Zhi am Sitz des Geistererweckers auf der Terrasse der Zehn Donner.", completion = "Dies muss ein Zeitalter großer Kämpfe sein, wenn es solche Helden wie Euch hervorbringt. Ich erwarte, dass große Abenteuer vor Euch liegen.\n\nEs war mir eine Ehre, Euch kennengelernt zu haben, {name}.\n\nIch werde hier bleiben, bis die letzten Geister den Tan-Chao passiert haben und dann selbst hinübergehen.\n\nAber der Todesfluch des Geistererweckers macht mir immer noch Sorgen...\n\n\"Ihr werdet den Donner nicht besiegen können.\"\n\nWas kann er damit gemeint haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[29756] = { id = 29756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bescheidenes Opferangebot", description = "Ich bin fast bereit für das Ritual - wir benötigen nur noch eine einzige Sache. Eine Opfergabe.\n\nKeine Sorge, ich meine kein Blutopfer. Nur etwas Nahrung.\n\nIm Gezeitenblickdickicht im Nordwesten wachsen ganz sicher ein paar Pilze, die sich dafür eignen. Bitte bringt mir einige davon.", sourceObjective = "Sammelt 10 Gezeitennebelkappen im Gezeitenblickdickicht ein.", progress = "Selbst Tote haben Hunger.", completion = "Ich danke Euch, {name}. Diese Pilze machen als Opfergabe vielleicht nicht viel her, aber die Erinnerung an sie wird ausreichen, die Geister anzulocken.\n\nAußerdem schmecken sie gebraten ganz köstlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[29757] = { id = 29757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trötenkröten", description = "Habt Ihr von den Problemen bei den Teichen gehört?\n\nDie Kröten dort vermehren sich wie verrückt! Das ist zu einem echten Problem für die Lotusbauern geworden.\n\nZufälligerweise stelle ich eine Marmelade aus gallertartigem Froschlaich her. Ich nenne sie \"Trötenkröten\" und sie kommt bei der Jugend hier sehr gut an. Ich kann die nicht lange auf Lager halten.\n\nWenn Ihr zu den Teichen unterwegs seid, könntet Ihr allen einen Gefallen tun, indem Ihr einige dieser Kröteneier, ähm... befreit.\n\nUnd in diese Flasche befördert. Für mich.\n\nHaltet einfach nach Blasen Ausschau und schöpft daraus!", sourceObjective = "Holt Kröteneier von 8 Blasen gurgelndem Froschlaich aus dem oberen Bereich der Teiche der Reinheit.", completion = "Wenn die Kinder mich jetzt fragen: \"Habt Ihr Trötenkröten?\" - Dann kann ich mit JA antworten!", sourceObjectiveStatus = "unverified-source-field" }
quests[29758] = { id = 29758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schöner Rücken kann entzücken", description = "<Der Panzer dieser Drachenschildkröte ist hart wie Stein und tief zerfurcht. Einer der Einheimischen kann damit bestimmt etwas anfangen.>", sourceObjective = "Bringt Kroshs Rücken zu Yan in Neu-Cifera.\n\nBereitgestellter Gegenstand:", completion = "Jetzt schaut Euch DAS an! Was für ein wunderschöner Panzer!\n\nGut, dass Ihr ihn zu mir gebracht habt. Er ist ideal für einen fantastischen Servierteller.\n\nBitte, nehmt dies als Dank für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29759] = { id = 29759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kung Din", description = "Ich hoffe, Ihr seid dieser nächsten Aufgabe gewachsen, denn unsere Leben hängen davon ab.\n\nEs gibt nur einen Schlüssel, um uns von unseren Ketten zu befreien. Und leider hängt dieser Schlüssel um den Hals des Haustigers der Ho-zen, Kung Din.\n\nSie halten den Tiger in der großen Grube im Norden. Um den Schlüssel zu erhalten, muss man den Tiger allerdings töten.", sourceObjective = "Holt Euch den Schlingschwanzschlüssel, indem Ihr Kung Din tötet.", progress = "Habt Ihr ihn gefunden?", completion = "Ja, mit diesem Schlüssel kann ich uns von unseren Ketten befreien.\n\nIhr habt uns von diesem widerwärtigen Ort erlöst.", sourceObjectiveStatus = "unverified-source-field" }
quests[29760] = { id = 29760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grubenkämpfer", description = "Um ein meisterhafter Grubenkämpfer zu werden, muss man sicherlich noch mehr machen...\n\nVielleicht weiß Korgol Schädelquetscher, der die Todesgrube des Dunkelmond-Jahrmarkts auf dem Dunkelmond-Jahrmarkt leitet, mehr.", sourceObjective = "Sprecht mit Korgol Schädelquetscher auf dem Dunkelmond-Jahrmarkt.\n\nBereitgestellter Gegenstand:", completion = "Schön, Euch zu sehen, {class}.\n\nEin Schmuckstück reicht nicht, um ein meisterhafter Grubenkämpfer zu werden.\n\nEs ist an der Zeit, dass Ihr beweist, was in Euch steckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29761] = { id = 29761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meisterhafter Grubenkämpfer", progress = "Schön, Euch wiederzusehen, {class}.\n\nBringt mir 12 Schmuckstücke des Grubenkämpfers, und ich mache Euch zum meisterhaften Grubenkämpfer des Dunkelmond-Jahrmarkts!", completion = "Ihr habt viele Kämpfer besiegt und viele Zuschauer unterhalten.\n\nHiermit ernenne ich Euch zum meisterhaften Grubenkämpfer des Dunkelmond-Jahrmarkts." }
quests[29762] = { id = 29762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familienandenken", description = "Wir haben vor Kurzem eine harte Schlacht gegen die Ho-zen in der Mondwasserzuflucht verloren.\n\nWir haben so viele Leute rausgeholt wie nur irgend möglich, aber dennoch haben viele von uns dort ihr Leben gelassen.\n\nWir haben keine Andenken an die Toten für unsere Gebete.\n\nWenn jemand ein paar Andenken von den Toten nehmen könnte, könnten wir sie in Frieden gehen lassen und mit dem Leben fortfahren.\n\nEs würde uns wirklich viel bedeuten, wenn Ihr das tun könntet, {name}.", sourceObjective = "Sammelt 8 Perlflossenerbstücke von den toten Perlflossendorfbewohnern in der Mondwasserzuflucht ein.", progress = "Wir trauern immer noch um unsere gefallenen Brüder.", completion = "Ich danke Euch, {name}. Ihr könnt Euch gar nicht vorstellen, wie viel dies den Familien der Toten bedeutet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29763] = { id = 29763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt ihnen den Donner", description = "Die Vrykul kennen keine Angst. Sie scheinen sich sogar nach einem Tod in der Schlacht zu sehnen. Sie sind so zahlreich und werfen sich mit solcher Macht in den Kampf, dass wir nichts gegen sie ausrichten können.\n\nEs gibt jedoch einen, den sie verehren. Sein Name ist Ingvar. Wenn Ihr ihn töten könntet, würde das ihre Kampfeslust deutlich bremsen.", sourceObjective = "Verteidiger Mordun hat Euch gebeten, ihm den Kopf von Ingvar dem Brandschatzer zu bringen.", progress = "Schön zu sehen, dass es Euch gut geht, {name}.\n\nWeitere Verluste könnten wir nicht verkraften.", completion = "Hervorragend!\n\nDas könnte der Durchbruch sein, auf den wir gehofft haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29764] = { id = 29764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abrüstung", description = "Ihr könnt mir glauben, <Kamerad/Fräulein>, diese Vrykulwaffen sind verdammt unangenehm! Trügerisch gut ausbalanciert, brutal scharf - absolut tödlich.\n\nKlaut mir ein paar davon, bevor sie gegen uns eingesetzt werden.", sourceObjective = "Verteidiger Mordun möchte, dass Ihr 5 Waffen der Vrykul stehlt.", progress = "Habt Ihr ein paar Äxte der Vrykul geklaut?", completion = "<Mordun pfeift.>\n\nSeht Euch die nur mal an! Unglaublich.\n\nIch hatte eigentlich erwartet, dass diese Steinzeitmenschen mit Knüppeln herumfuchteln und Steine werfen.\n\nLeider nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[29765] = { id = 29765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich heul' mir die Augen aus", description = "Ich hätt' die Schweine fertigmach'n können, Mann!\n\nIhnen alle eine reinschieß'n und mich dann totstell'n, wenn sie näherkomm'n! Hab'n die sonst ja auch nie kapiert.\n\nAber einer von denen hat den Trick jetzt doch kapiert... Und dann sind die alle auf mich rauf und hab'n mit meinen Augen Murmeln gespielt.\n\nHab'n meine Sachen genommen und mich hier zum Sterb'n einfach liegengelass'n, diese Wilden...\n\nDu musst mir helf'n, Mann. Lass' mich nich' so würdelos sterb'n.", sourceObjective = "Nehmt den Ho-zen-Wutschäumern Zin'Juns Sachen wieder ab.\n\nWenn Ihr Zin'Jun verliert, sprecht mit ihm am Aufstieg der Wirbelnden Winde.", progress = "Hast du meine Sachen, Mann?", completion = "<Zin'Jun schluchzt... Glaubt Ihr jedenfalls.>\n\nDie hab'n Schnuff umgebracht...\n\nWas hat Schnuff denen denn getan?", sourceObjectiveStatus = "unverified-source-field" }
quests[29766] = { id = 29766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein guter Start", description = "Unabhängig von unserer misslichen Lage sind unsere Befehle klar. Wir sind hier, um das Land zu erkunden und es für Höllschreis Flotte vorzubereiten.\n\nAber zuerst müssen wir mit diesen Wilden fertigwerden!\n\nSeht Ihr die Leichen, die ich um das Lager herum aufgestapelt habe? Ich will ganze Berge davon sehen!\n\nWir sind immer noch die Horde!\n\nDiese Maden haben noch nicht gelernt, uns zu fürchten, aber das wird sich schon bald ändern...", sourceObjective = "Tötet 4 Ho-zen-Schlickschleuderer, 4 Ho-zen-Schädelbrecher und 3 Ho-zen-Fischfänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[29767] = { id = 29767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischimbiss", description = "Das Glück belohnt die Mutigen!\n\nEure kühl kalkulierten Angriffe haben unerwartete Wirkung gezeigt. Wenn Ihr diese Fischfänger töten könnt, nachdem sie einen guten Fang gemacht haben, könnt Ihr ihnen ihre fischige Beute abnehmen.\n\nDie Feinde ausdünnen und die Verbündeten nähren - das nenne ich Effizienz!", sourceObjective = "Nehmt den Ho-zu-Fischfängern 12 ausgewachsene Karpfen ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[29768] = { id = 29768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der fehlende Schlägel", description = "{name}, ich hab's! Es ist eigentlich ganz simpel. Wir müssen einfach so viel Rabatz machen, dass er keine Chance hat, davor die Ohren zu verschließen.\n\nSieh mal einer an, dieser Gong hier steht aber genau am rechten Fleck! Wenn ich mich nicht irre, dann haben sie ihn bisher wohl auf genau diese Weise aufgeweckt. Wir brauchen nur den passenden Schlägel, damit der Gong so laut wie möglich wird.\n\nDer Dorfvorsteher hat mir erzählt, dass sich der Schlägel bei der Brauerei Ki-Han am Fluss südwestlich von hier befindet. Es ist nicht weit. Macht es Euch etwas aus, ihn für mich abzuholen, während ich hier das Dorf vorwarne?", sourceObjective = "Beschafft den Dai-Lo-Pausenhammer bei der Brauerei Ki-Han.", progress = "Nun, sie sind gewarnt, dass es gewarnter nicht mehr geht. Habt Ihr den Schlägel?", completion = "Ha, {name}! Das nenne ich einen Schlägel. Dann wollen wir mal auf die Pauke - oder eher den Gong - hauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29769] = { id = 29769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strolche!", description = "Ich suche weiter nach Möglichkeiten, diesen hartnäckigen Tiefschläfer hier aufzuwecken, aber auf dieser Insel lauert einfach an jeder Ecke ein neues Ärgernis. Die komplette Vegetation im Süden ist mit Shed-Ling verseucht, hasenartigen Dieben und Plünderern.\n\nDiese Strolche!\n\nSie vermehren sich schneller, als wir sie töten können! Aber ich habe genau die richtige Lösung für ein Problem wie dieses: Tötet sie schneller! Jetzt, da Ihr hier seid, sollte das ja kein Problem mehr sein, oder was sagt Ihr, {name}?", sourceObjective = "Tötet 10 Shed-Ling.", completion = "So wird das gemacht, {name}! Ihr taucht auf und Probleme lösen sich fast wie von selbst. Das ist nur einer der vielen Gründe, warum ich Euch mag!", sourceObjectiveStatus = "unverified-source-field" }
quests[29770] = { id = 29770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch essbar", description = "Die Shed-Ling im Süden sind mit einem Großteil der Ernte davongerannt, aber sie haben sich mehr geschnappt, als sie essen können. Sie müssen ihre Beute irgendwo lagern – zumindest den Teil davon, den sie mögen.\n\nKönntet Ihr Euch auf die Suche machen und die Feldfrüchte zurückbringen? Ich habe hier eine ganze Insel zu versorgen und jedes bisschen Gemüse hilft mir dabei.", sourceObjective = "Beschafft 3 ausgegrabene Rüben, 3 gestohlene Karotten und 3 stibitzte Kürbisse wieder.", progress = "Seit Wugou, der Geist der Erde, eingeschlafen ist, ist der Boden trockener geworden und es wird immer schwerer, neue Saat zum Sprießen zu bringen. Wir müssen so viele Lebensmittel wie möglich horten - ansonsten wird der Insel eine harte Zeit bevorstehen.", completion = "Einige hiervon sind ja angebissen! Ach, was soll's... Wir finden schon einen Verwendungszweck.\n\nVielen Dank für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[29771] = { id = 29771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Härter als Holz", description = "Besorgt mir ein paar Holzbretter von der Baustelle in der Nähe der Brauerei Ki-Han.\n\nIhr kennt die Größe meiner Stärke noch nicht, daher werde ich sie Euch demonstrieren.", sourceObjective = "Sammelt 12 weggeworfene Holzbretter.", progress = "Habt Ihr erledigt, was ich Euch aufgetragen hatte?", completion = "Gut.\n\nMein Kopf ist härter als das härteste Holz.\n\nTretet zurück und lasst mich Eure Zweifel zerstreuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29772] = { id = 29772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabatz", description = "Seid Ihr bereit, {name}? Ich glaube, dass wir uns besser etwas besorgt hätten, das wir uns in die Ohren stopfen könnten, aber dafür ist es jetzt ein bisschen zu spät. Denkt einfach immer daran, dass das fiepende Geräusch, dass Ihr für die nächsten paar Stunden hören werdet, das Fiepen des Sieges ist!\n\nDie Ehre gebührt Euch, {name}. Schlagt den Gong, sobald Ihr bereit seid!", sourceObjective = "Schlagt den Gong.", progress = "Nun macht schon, {name}! Die Anspannung bringt mich ja fast um!", completion = "Hmm... Nun, das ist definitiv das Fiepen, dass ich befürchtet hatte, aber ich hatte mir etwas mehr Reaktion von Wugou erhofft. Dieser Kerl schläft wirklich tief, so viel ist sicher.\n\nDas ist schon in Ordnung, {name}. Ich habe noch eine andere Idee, für die wir kaum etwas vorbereiten müssen. Genau, wie ich es mag.", sourceObjectiveStatus = "unverified-source-field" }
quests[29773] = { id = 29773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wugou, der Geist der Erde", description = "{name}! Nun, die gute Nachricht ist, dass Wugou ziemlich einfach zu finden war. Die schlechte ist, dass er einen wirklich tiefen Schlaf hat. Er wird wohl mit einem ziemlich steifen Nacken aufwachen nach all dem Geschiebe und Getrete, mit dem ich ihn schon zu wecken versucht habe.\n\nHabt ihr auch so einen tiefen Schlaf, {name}? Was bringt Euch morgens aus dem Bett?\n\nIch rolle mich immer aus dem Bett - zumindest bei mir scheint das zu funktionieren. Vielleicht auch bei Wugou? Ich habe ein paar Seile an diesem Ochsenkarren dort festgemacht. Wir setzen ihn in Bewegung und der Rest sollte ein Selbstläufer sein. Wollt Ihr dem Ochsen einen ordentlichen Klaps verpassen, damit er in die Gänge kommt?", sourceObjective = "Verpasst dem Ochsen einen Klaps.", sourceObjectiveStatus = "unverified-source-field" }
quests[29774] = { id = 29774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht ins Gesicht!", description = "Nun gut, {name} - ich hatte mir schon Gedanken darüber gemacht, was wir wohl probieren könnten, falls die Idee mit dem Gong nicht funktionieren würde, und es ist mir einfach so eingefallen! Ein Schwall kaltes Wasser ins Gesicht macht mich immer hellwach! Und bei jemandem, der so trocken und erdig ist, muss das gleich den doppelten Effekt haben!\n\nKönntet Ihr Shu, den Geist des Wassers, vielleicht darum bitten, uns auszuhelfen? Er sollte in dem Teich neben dem Wasserfall auf der anderen Seite des Baumes spielen.", sourceObjective = "Erbittet Shus Hilfe, um Wugou aufzuwecken, den Geist der Erde.", completion = "JUHU! {name}, wir sind schon ein tolles Team. Wie ich immer zu sagen pflege: Hartnäckigkeit ist besser als Planung.", sourceObjectiveStatus = "unverified-source-field" }
quests[29775] = { id = 29775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Körper und Geist von Shen-zin Su", description = "So, damit wären wir hier fertig, oder nicht? Nun, da diese beiden hier Euch liebgewonnen haben, müssen wir sie nur noch zum Tempel der Fünf Sonnenaufgänge zurückbringen.\n\nGeht ruhig schon vor. Ich verabschiede mich hier noch und komme dann nach.", sourceObjective = "Bringt Shu und Wugou, die Geister des Wassers und der Erde, zum Tempel der Fünf Sonnenaufgänge. An der Straße steht ein Wagen, der Euch dorthin bringen wird.", completion = "Ihr habt Euch sehr gut geschlagen, mein junger Schüler. Drei der vier Geister sind in den Tempel zurückgekehrt. Wir sind den Antworten, die wir suchen, ein bedeutendes Stück näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[29776] = { id = 29776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenhauch", description = "Der vierte und letzte Geist ist Dafeng, der Geist des Windes. Wenn er sich gerade nicht durch die Himmel schwingt, hält er sich auf dem Grat der Lachenden Winde westlich von hier auf. Ich habe sowohl Aysa als auch Ji dorthin geschickt, um Euch bei der Suche zu helfen.\n\nWenn Ihr bereit seid, werde ich helfende Winde beschwören, die Euch zur Spitze des Tempels tragen werden. Von dort aus müsst Ihr die Brücken nach Westen überqueren, um Ji in Morgenhauch zu treffen.", sourceObjective = "Trefft Ji Feuerpfote in Morgenhauch.", completion = "{name}, lasst Euch umarmen! Diesmal waren wir ja nicht allzu lang getrennt - gut so!\n\nIhr habt mit Aysa zusammengearbeitet, oder? Unsere verschiedenen Überzeugungen haben uns lange Zeit voneinander ferngehalten, deshalb weiß ich nur wenig über sie. Aber jetzt, da ich sie ihre Rituale durchführen sehe, muss ich zugeben, dass sie mit ihrer Anmut und Disziplin einen seltsam verlockenden Eindruck auf mich macht.\n\nAber wir sollten unsere Gedanken dringenderen Angelegenheiten zuwenden, denkt ihr nicht? {name}, nehmen wir uns dieses Affenproblems an, während wir nach Dafeng suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29777] = { id = 29777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Werkzeuge des Feindes", description = "Die Ho-zen haben unsere Pinsel gestohlen und beschmieren unsere Schriftrollen mit ihren eigenen \"Weisheiten\"... wenn man das so nennen darf. Falls Ihr hier seid, um zu helfen, dann haltet sie auf und bringt uns unsere Pinsel zurück, bevor sie noch mehr Schaden anrichten können!", sourceObjective = "Beschafft 8 farbgetränkte Pinsel wieder.", progress = "Ich möchte die Ho-zen nicht für ihre Ambitionen verunglimpfen - jedes Volk muss seinen eigenen Weg gehen. Was diesen Vorfall betrifft, gefährden sie aber unser Leben und unsere Kultur. Das können wir nicht zulassen", completion = "Ich bin Euch zu Dank verpflichtet, junger {class}. Schon bald werde ich mit der mühseligen Arbeit beginnen, unsere Weisheiten erneut niederzuschreiben, damit die Schriftrollen wieder aufgehängt werden können, um nachfolgende Generationen zu leiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29778] = { id = 29778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umgeschriebene Weisheiten", description = "{name}, wir müssen dem Ältesten Shaopai helfen. Es gibt nur wenige, die unsere Güte mehr verdient hätten als er.\n\nAuf dem Weg hierher sind Euch bestimmt die Schriftrollen aufgefallen, die in der Grotte im Süden hängen. Die Ho-zen haben viele davon besudelt und leider kann der Schaden nicht rückgängig gemacht werden. Wir werden uns des Problems auf direkte Art annehmen - indem wir die Schriftrollen zusammen mit den Schmierereien der Ho-zen vernichten.\n\nSorgt Euch nicht um Shaopai. Die Leute werden zusammenkommen und ihm dabei helfen, die Weisheiten erneut niederzuschreiben. Dafür werde ich sorgen.", sourceObjective = "Verbrennt 5 verschandelte Rollen der Weisheit.", completion = "Ihr seid herzensgut, {name}. Ihr beweist das stets aufs Neue und ich bin froh, an Eurer Seite stehen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29779] = { id = 29779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der direkte Weg", description = "Jetzt reicht's, {name}. Das ist das zweite Mal, dass wir uns mit plündernden Ho-zen herumschlagen mussten. Es ist an der Zeit, dass wir uns um das Problem kümmern - auf die Huojin-Art. Kein Abwarten mehr. Keine Meditation. Wir werden das Übel bei der Wurzel packen.\n\nWir gehen direkt ins Ho-zen-Dorf im Norden und bestrafen diese stinkenden Unruhestifter. Ich hatte mich schon darauf gefreut, endlich wieder an Eurer Seite kämpfen zu dürfen, {name}.", sourceObjective = "Tötet 20 Ho-zen in Fe-Feng.", completion = "Das belebt Körper und Geist! Nach einem guten Kampf fühle ich mich stets besser...", sourceObjectiveStatus = "unverified-source-field" }
quests[29780] = { id = 29780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Unrecht tun", description = "{name}, Ihr müsst verstehen, dass der Weg der Huojin keineswegs der Weg der Gewalt ist. Wenn wir kämpfen müssen, zögern wir keinen Moment, aber wenn wir nicht kämpfen müssen, werden wir auch keinen Kampf anzetteln. Allerdings ist es oft der direkteste Weg, der Schlange den Kopf abzuschlagen, wie es so schön heißt.\n\nDie Ho-zen haben einen Anführer, der all diese Angriffe auf unsere Siedlungen anzettelt. Wenn wir Ruk-Ruk aus dem Spiel nehmen, müssen wir nicht alle Ho-zen ausrotten, um die Angriffe zu stoppen.\n\nIch weiß, dass Ihr kein Anhänger der Huojin seid, {name}, aber Ihr werdet mir sicher dabei helfen, das zu tun, was getan werden muss, oder?", sourceObjective = "Tötet Ruk-Ruk, den Häuptling von Fe-Feng.", completion = "Ich glaube, dass in Euch ein kleiner Huojin steckt, {name}. Hört nur auf mich und vielleicht werdet Ihr Euch eines Tages für diesen Weg entscheiden!", sourceObjectiveStatus = "unverified-source-field" }
quests[29781] = { id = 29781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Affen unzugänglich aufbewahren", description = "Die Affen haben sich bei ihren Angriffen auf das Dorf etliches unter den Nagel gerissen. Wir sollten den Verlust einiger Proviantpakete verkraften können, aber bei dem Gedanken an Affen mit Feuerwerkskörpern wird mir ein wenig flau im Magen. Außerdem weiß man ja nie, wann wir selbst einmal ein paar Raketen benötigen, nicht wahr?\n\nHelft mir, die gestohlenen Feuerwerkskörper aus ihrem Dorf zurückzuholen, {name}!", sourceObjective = "Beschafft 8 gestohlene Feuerwerksbündel wieder.", progress = "Mich verwundert schon allein, dass sie mit diesen Dingern nicht ihr eigenes Dorf in Brand gesteckt haben.", completion = "{name}, wir sollten mit diesen Dingern später unseren Erfolg feiern. Was meint Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[29782] = { id = 29782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Härter als Knochen", description = "Diese große Säule des Jadetigers scheint unter all diesen Ho-zen-Gebäuden fehl am Platz zu sein.\n\nSie macht aber auch einen sehr harten Eindruck. Wirklich sehr hart.\n\nIhr wisst genau, wer sich dafür interessieren dürfte.", sourceObjective = "Bringt die Säule des Jadetigers zu Jojo Eisenstirn in Morgenhauch.\n\nBereitgestellter Gegenstand:", completion = "GUT! Eine echte Herausforderung. Lasst uns diese Säule auf die Probe stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29783] = { id = 29783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Härter als Stein", description = "Sammelt ein paar Steinblöcke beim Grat der Lachenden Winde im Süden für mich.\n\nIhr konntet Euch nun schon zweimal von meiner Stärke überzeugen, doch Euer Blick verrät mir, dass Ihr immer noch zweifelt... aber nicht mehr lange.", sourceObjective = "Sammelt 12 herrenlose Steinblöcke.", progress = "Die Stärke des Körpers kann ohne die Stärke des Geistes nicht existieren.", completion = "Gut.\n\nMein Kopf ist härter als der härteste Stein.\n\nTretet zurück und lasst mich Eure Zweifel zerstreuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29784] = { id = 29784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Gleichgewicht", description = "Aysa hat auf dem See meditiert, seit wir hier angekommen sind. All ihre Gedanken sind auf Dafeng gerichtet. Ich weiß nicht, was sie sich dort draußen zu finden erhofft, aber sie ist kein Dummkopf und Meister Shang Xi persönlich hat sie mit dieser Aufgabe betraut.\n\nIhr werdet über die Seile, die am Ende des Docks festgemacht sind, zu ihr gelangen müssen. Das wird Eure Balance auf die Probe stellen, aber ich denke, dass Ihr der Herausforderung gewachsen seid.", sourceObjective = "Balanciert über die Seile und sprecht mit Aysa Wolkensänger auf dem Morgenhauchsee.", completion = "Ich bin beeindruckt. Die meisten Schüler, die überhaupt in der Lage sind, diesen Ort zu erreichen, kommen normalerweise patschnass an.", sourceObjectiveStatus = "unverified-source-field" }
quests[29785] = { id = 29785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dafeng, der Geist des Windes", description = "Wenn Ihr nur lang genug zuhört, wird der Wind Euch die Antwort zutragen.\n\nDafeng, der Geist der Luft, hat den Himmel aus Furcht vor der Onyxschlange Zhao-Ren verlassen. Er versteckt sich in der Kammer des Raunens an der Südseite des Plateaus.\n\nGeht zu ihm. Ji und ich werden dort zu Euch stoßen.", sourceObjective = "Sprecht mit Dafeng, dem Geist der Luft, in der Kammer des Raunens.", completion = "Dafeng macht einen ängstlichen Eindruck, als Ihr auf ihn zugeht, aber er beruhigt sich, als Ihr zu sprechen beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29786] = { id = 29786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht um den Himmel", description = "Dafeng, der Geist der Luft, hat furchtbare Angst vor der Onyxschlange Zhao-Ren, {class}. Wir müssen ihm helfen, sich seiner Angst zu stellen, oder ihr an seiner statt gegenübertreten.\n\nAls ich Ji von der Schlange erzählt habe, sagte er, er habe eine Idee. Er wollte außerhalb der Kammer mit den Vorbereitungen beginnen. Ich muss zugeben, dass ich ihn trotz seiner unbesonnenen Art um seine Leidenschaft und Überzeugung beneide.\n\nLasst uns nach draußen gehen, um uns der Onyxschlange zu stellen.", sourceObjective = "Besiegt die Onyxschlange Zhao-Ren mithilfe von Jis Feuerwerk.", completion = "Ihr habt Dafeng, dem Geist der Luft, geholfen, wieder Mut zu fassen! Der letzte Geist wurde wieder aufgebaut.", sourceObjectiveStatus = "unverified-source-field" }
quests[29787] = { id = 29787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweis der Würdigkeit", description = "Die vier Elementargeister werden Euch dabei helfen, mit dem Land zu sprechen und herauszufinden, woran es leidet, aber vorher habe ich noch eine kleine Aufgabe für Euch.\n\nKommt mit. Begleitet diesen alten Pandaren zum Gehölz im Westen.", sourceObjective = "Besiegt den Wächter der Ältesten.", completion = "Ich verfüge nicht mehr über die körperliche Stärke und Willenskraft, die mir einst zu eigen waren. Ich bin froh, dass edle {race} wie Ihr nun für unser Volk kämpfen. Ihr habt beachtliche Fortschritte gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29788] = { id = 29788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unschöne Natur", description = "Ihr hattet es schon einmal mit Waldgeistern im Tal des Anbrechenden Morgens zu tun, aber die Waldgeister in diesem Gehölz sind von einer komplett anderen Sorte. Gemeiner und gefährlicher.\n\nFalls Ihr ein paar dieser Wichte beseitigen könntet, wären die Elementargeister Euch dankbar.", sourceObjective = "Tötet 8 Dornzweigstrolche.", completion = "Die Geister danken Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29789] = { id = 29789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klein, aber wichtig", description = "Ich bin müde, {name}. Ich muss mich ausruhen.\n\nWir müssen ein Ritual durchführen, aber wir benötigen einige der Talismane aus diesem Gehölz. Wenn Ihr es durchsucht, solltet Ihr sie überall von den Bäumen hängen sehen.\n\nIch nehme an, dass es einem jungen Hüpfer wie Euch nichts ausmacht, wenn ich mich hier hinsetze und ein wenig ausruhe, während Ihr die Talismane sammelt?", sourceObjective = "Sammelt 8 Kun-Pai-Ritualtalismane.", progress = "Diese Pause tut mir gut. Die Last des Alters wiegt nach all diesen Jahren schwer auf meinen Schultern.", completion = "Ihr wart erfolgreich – wie stets zuvor. Ihr seid wahrlich einer meiner großartigsten Schüler. Ich glaube, aus Euch könnte eines Tages ein {class} werden, wie ihn die Welt noch nie gesehen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[29790] = { id = 29790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weisheit überliefern", description = "Ihr werdet Eure Reise schon bald ohne mich fortsetzen müssen. Bleibt ein Weilchen und lauscht den Worten eines alten Mannes. Mein Wissen soll als Fundament des Euren dienen, sodass Ihr zu einem größeren Helden werden könnt, als ich es jemals war.", sourceObjective = "Hört Meister Shang Xi zu.", completion = "Ich weiß, {name}... Ich weiß. So spielt das Schicksal nun einmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29791] = { id = 29791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Leiden von Shen-zin Su", description = "Die Zeit der Trauer wird noch kommen. Aber der Ballon steht bereit und Shen-zin Su erwartet uns.\n\nWir werden die ersten Pandaren sein, die nach Hunderten von Jahren wieder mit Shen-zin Su sprechen dürfen. Es ist eine große Ehre.", sourceObjective = "Steigt in den Heißluftballon ein und sprecht mit Shen-zin Su.", completion = "Euch ist eine große Ehre zuteilgeworden, {class}. Welche Weisheiten könnt Ihr uns überbringen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29792] = { id = 29792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Großem berufen", description = "Es liegt nun an euch allen, den Stachel aus dem Fleisch Shen-zin Sus zu entfernen. Lasst eure Unterschiede nicht zu einem Hindernis werden. Habt Vertrauen ineinander.\n\nIm Pei-Wu-Wald lebt ein Einsiedler. Begebt euch geradewegs zu seiner Hütte. Er weiß genau, was für dunkle Gestalten sich dieser Tage in den Bäumen verstecken.", sourceObjective = "Öffnet das Tor zum Pei-Wu-Wald.", completion = "Das Böse erhebt sich aus dem Meer und erfüllt den Wald. Es sind nicht mehr nur die Tiger, vor denen man sich in Acht nehmen muss... etwas deutlich Dunkleres lauert in den Schatten und wartet nur darauf, dass ein unbedachter {race} allein des Weges kommt.\n\nIhr seid hier nicht sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[29793] = { id = 29793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Böse aus dem Meer", description = "Ich weiß nicht genau, was dieses Böse ist, das den Wald befallen hat, {name}, aber ich weiß genau, was man dagegen tun kann. Ich denke, Ihr wisst, was ich meine...", sourceObjective = "Tötet 8 verfinsterte Gräuel oder verfinsterte Schrecken.", completion = "Ihr macht mich stolz, {name}. Ihr macht uns alle stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[29794] = { id = 29794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keiner wird zurückgelassen", description = "Eure Freundin hat keine Mühen gescheut, um meine Besatzung zu retten. Ich bin ihr zu tiefstem Dank verpflichtet.\n\nWir haben hier aber immer noch mit zu vielen Problemen gleichzeitig zu kämpfen: Die Feuer am Wrack müssen gelöscht, die Leute herausgeschafft und die Gefangenen an der Flucht gehindert werden. Wir schaffen das einfach nicht allein.\n\nDa sind immer noch Besatzungsmitglieder auf dem Schiff, die wir herausholen müssen, bevor das Wrack über ihnen zusammenbricht. Ich weiß, dass ich viel von Euch verlange, aber könntet Ihr uns helfen?", sourceObjective = "Rettet 3 verletzte Matrosen.", completion = "Ich habe zwar keine Ahnung, wer oder was Ihr und Euer Volk seid, aber das Schicksal war uns heute sicherlich wohlgesonnen. Es hätten noch viel mehr von uns zu Tode kommen können, wenn Ihr und Eure Freunde nicht gewesen wärt. Ich stehe in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[29795] = { id = 29795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohre raffen", description = "Meine Männer sind unterernährt, verwundet und erschöpft, aber sie sind von der Horde. Ein jeder von ihnen wird bis zum letzten Atemzug kämpfen. Ihr seid unser neuer Verbündeter und wir werden Euch zur Seite stehen, wenn die Zeit reif ist, aber wir wären eine weitaus größere Hilfe, wenn wir bewaffnet wären.\n\nIch habe meine Männer beauftragt, Bambusrohre aus der Umgebung zusammenzusammeln, die wir zu Speeren umfunktionieren könnten. Falls es Euch nichts ausmacht, könnten wir dabei ein weiteres Paar kräftige Hände gut gebrauchen.", sourceObjective = "Sammelt 10 abgebrochene Bambusrohre.", progress = "Die Horde stellt sich jedem Kampf.", completion = "Die hier sind wunderbar! Wir werden sie in null Komma nichts zu Waffen verarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29796] = { id = 29796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dringende Neuigkeiten", description = "Ich bin mir sicher, dass Aysa dieser Plan nicht gefallen wird, aber es ist der einzige Plan, den wir haben. Würde es Euch etwas ausmachen, an meiner Stelle der Überbringer schlechter Nachrichten zu sein, {name}? Sie muss wissen, was wir vorhaben, damit sie alle in Sicherheit bringen kann.", sourceObjective = "Sprecht mit Delora Löwenherz beim Wrack der Himmelssucher.", completion = "Eure Freundin kämpft um das Leben meiner Besatzung - und das mit vollem Einsatz. Eure Nachricht wird leider ein wenig warten müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29797] = { id = 29797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medizinische Versorgungsgüter", description = "Wir brauchen Medikamente und Verbandszeug, um uns um unsere Verwundeten zu kümmern, aber ich habe keine Ahnung, was mit den Kisten, in denen all das verstaut war, beim Absturz passiert ist. Wenn Ihr einfach ein paar Kisten wiederfinden könntet, dann wäre ich Euch sehr dankbar.", sourceObjective = "Beschafft 8 Kisten mit medizinischen Versorgungsgütern wieder.", progress = "Habt Ihr die Kisten gefunden, von denen ich Euch erzählt hatte?", completion = "Die hier sind perfekt. Unsere Sanitäter werden sich sofort an die Arbeit machen.\n\nVielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[29798] = { id = 29798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein uraltes Übel", description = "{name}, ich habe nach Euch gesucht!\n\nEiner der entkommenen Seeleute hat Aysa im Schiffswrack gesehen, wie sie einem gigantischen Ungeheuer gegenüberstand. Sie braucht wahrscheinlich Eure Hilfe... Eilt zu ihr, schnell!", sourceObjective = "Bezwingt Vordraka, den Alptraum aus der Tiefe.", completion = "<Der Kampf hat Aysa offensichtlich erschöpft.>\n\nEure Fähigkeiten im Kampf... stehen außer Frage... {class}.\n\n\n\nHabt Ihr die entkommenen Gefangenen gerettet? ... Wo ist Ji? Geht es ihm gut?", sourceObjectiveStatus = "unverified-source-field" }
quests[29799] = { id = 29799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heilung von Shen-zin Su", description = "Das ist viel schlimmer, als ich erwartet hatte, aber wir können es schaffen. Wir müssen alle Heiler Shen-zin Sus zusammentrommeln, um die Wunde zu schließen. Wir müssen Shen-zin Su retten.\n\nFindet so viele Heiler, wie Ihr nur könnt! Befreit sie, entbindet sie von anderen Aufgaben - tut, was immer Ihr tun müsst, damit sie hierherkommen und diese Wunde heilen.\n\nUnd passt auf, dass ihnen dabei nichts zustößt...", sourceObjective = "Rettet und beschützt die Heiler, bis Shen-zin Sus Wunde geheilt ist.", completion = "Ihr macht sogar einen noch eindrucksvolleren Eindruck, wenn Ihr unter Druck steht, {name}! Ohne Euch hätten wir nicht den Hauch einer Chance gehabt.\n\nIch glaube, es funktioniert. Die Blutung scheint gestoppt zu sein.\n\nIch wusste, dass es klappen würde!", sourceObjectiveStatus = "unverified-source-field" }
quests[29800] = { id = 29800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Verbündete", description = "Ich habe getan, was getan werden musste, {name}. Und es hat funktioniert. Es hätte alles viel schlimmer enden können, hätten wir nicht gehandelt. Ich wünschte nur, dass Aysa das verstehen würde.\n\nEs wird noch genug Zeit zur Besinnung geben, aber wir müssen zuerst zum Tempel der Fünf Sonnenaufgänge zurückkehren. Wir müssen sie wissen lassen, dass Shen-zin Su gerettet wurde - und wir müssen über das Schicksal dieser neuen Verbündeten entscheiden.", sourceObjective = "Kehrt zum Tempel der Fünf Sonnenaufgänge zurück. Beim Wrack der Himmelssucher wartet ein Wagen auf Euch der Euch zum Tempel bringen wird.", completion = "Schön, Euch wiederzusehen, {name}. Ihr habt alles getan, worum ich Euch gebeten habe... und sogar noch mehr: Ihr habt Shen-zin Su gerettet.\n\nIhr habt einen alten Meister sehr stolz gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29801] = { id = 29801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewährungsprobe", description = "Hallo, {name}! Im Schwarm hat sich herumgesprochen, dass Ihr ziemlich... wie soll ich sagen... geschickte Finger habt.\n\nWir könnten jemand mit Euren Fähigkeiten für eine äußerst delikate Aufgabe gebrauchen. Bevor ich fortfahre, muss ich wissen, ob Ihr <der richtige Mann/die richtige Frau> für diese Angelegenheit seid. Wenn Euch der Krieg zum Auge der Ewigkeit führt, möchte ich, dass Ihr Hagara die Sturmbinderin bestehlt und Ihr den Entschlüsselungsring eines Kryptomanten abnehmt. Wollt Ihr Euch dieser Aufgabe stellen?", sourceObjective = "Bestehlt Hagara die Sturmbinderin im Auge der Ewigkeit in der Drachenseeleninstanz und beschafft Euch so einen Entschlüsselungsring des Kryptomanten.", progress = "Habt Ihr unsere Aufgabe abgeschlossen? Diese Artefakte sind so konstruiert, dass sie sich auflösen, wenn ihr Träger getötet wird. Nur ein geübter Dieb kann sie beschaffen.", completion = "Ihr habt einen gefunden! Ihr seid eine Zierde für Euer Volk, {name}.\n\nMit diesen Ringen kann man sogar die kompliziertesten Chiffren entschlüsseln. Leider muss der Ring dazu erst aufgeladen werden...", sourceObjectiveStatus = "unverified-source-field" }
quests[29802] = { id = 29802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verborgene Botschaft", description = "Corastrasza, die sich momentan im Zinnoberrefugium im Schattenhochland aufhält, hat eine kodierte Botschaft von großer Wichtigkeit abgefangen. Sie wird Euch alles erklären, aber zuallererst brauchen wir Eure Hilfe bei der Entschlüsselung der Nachricht.\n\nBringt Euren Entschlüsselungsring zu einem astralen Thaumaturgen in Eurer Hauptstadt - er sollte wissen, wie man ihn auflädt. Lasst Euch die verschlüsselte Nachricht von Corastrasza geben und dekodiert sie mit Eurem Entschlüsselungsring. Beeilt Euch! Die Zeit läuft uns davon...", sourceObjective = "Ladet Euren Entschlüsselungsring des Kryptomanten auf und entschlüsselt damit Corastraszasangesengte Geheimnachricht.", progress = "Ich hatte gehofft, dass Lord Devrestrasz einen kompetenten Helfer finden würde.\n\nWas habt Ihr für uns, {name}? Könnt Ihr die Botschaft entschlüsseln?", completion = "Worum geht's, um das \"Rabenholdtanwesen\"? Ich dachte, da oben im Vorgebirge des Hügellandes gäbe es nur eine zusammengewürfelte Diebesbande.\n\nWas wollen die denn mit einem Drachenei? Und noch wichtiger: Wie haben sie davon erfahren?\n\nWir brauchen Antworten, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29803] = { id = 29803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ohren des Lichkönigs", description = "Im Fjord dient Prinz Keleseth als Arthas' Augen und Ohren.\n\nDas gefällt mir kein bisschen!\n\nMacht Arthas hier taub und blind. Damit erweist Ihr der Welt einen Gefallen.", sourceObjective = "Verteidiger Mordun in Burg Utgarde möchte, dass Ihr Prinz Keleseth tötet.", completion = "Ich wette, das hat dieses Blassgesicht gespürt!\n\nEin weiterer Schritt auf dem Weg zur Abrechnung, Arthas!", sourceObjectiveStatus = "unverified-source-field" }
quests[29804] = { id = 29804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für Schnuff!", description = "Ich wollt' eigentlich liegenbleib'n und abkratz'n, Mann.\n\nAber das geht jetzt nich'!\n\nSchnuff und ich war'n schon seit Ewigkeiten Kumpels. Was hatt'n wir für schöne Zeiten zusammen...\n\nAber ich muss erst Schnuff räch'n, Mann! Sonst kann ich ihm im Jenseits nich' unter die Augen tret'n!\n\nDer Anführer dieser Mistkerle heißt Konk. Er muss dran glaub'n - für Schnuff!", sourceObjective = "Tötet Konk.", completion = "Zin'Jun ist gestorben?\n\nWas für ein trauriger Tag, Bruder. Dafür muss dieses Gezücht bezahlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29805] = { id = 29805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Mishka auf Ebene gefunden" }
quests[29806] = { id = 29806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wanderer", sourceObjective = "Bezwingt den herumstreifenden Raufbold in einem Kampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[29807] = { id = 29807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod dem Verräterkönig", description = "Anub'arak der Verräterkönig ist im einst stolzen unterirdischen Azjol-Nerub zuhause.\n\nEr hat unsere Heimat in den erbärmlichen Haufen Dreck verwandelt, den wir heute sehen. Er herrscht über eine Armee untoter Neruber, die dem Lichkönig die Treue geschworen haben.\n\nSetzt der Herrschaft des Verräterkönigs ein Ende.", sourceObjective = "Pionier A'zak in Azjol-Nerub hat Euch aufgetragen, Anub'arak zu besiegen. Kehrt danach mit Anub'araks zerbrochenem Panzer zu A'zak zurück.", progress = "Ist es getan, {class}? Hat der Verräterkönig endlich sein Leben ausgehaucht?", completion = "<A'zaks Augen beginnen durchdringend zu leuchten, als er den Panzer anstarrt.>\n\nEs ist VOLLBRACHT!\n\n{race}! Euer Name wird in die Annalen meines Volkes aufgenommen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29808] = { id = 29808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergesst die Eier nicht!", description = "In ganz Azjol-Nerub liegen Eier, die von den Nerubern der Geißel gehegt und gepflegt werden. Die Jungen werden bald schlüpfen, um geschlachtet und als Untote wiedererweckt zu werden.\n\nDiese Eier wurden mit fauler Magie verunreinigt. Wir müssen sie unbedingt vernichten.", sourceObjective = "Pionier A'zak in Azjol-Nerub möchte, dass Ihr 6 Eier der Geißelneruber zerstört.", completion = "Keine Sorge, {race}.\n\nWir haben die meisten unserer Eier gut in Azjol-Nerub versteckt. Sie haben nur ein paar gefunden.\n\nUnser mächtiges Königreich wird wieder auferstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29809] = { id = 29809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Effiziente Ausgrabungen", description = "Dieses Handbuch beschreibt absonderliche Theorien, wie man große Arbeitergruppen wirksam einteilt, wenn sie mit gewaltigen Ausgrabungsprojekten beschäftigt sind.\n\nNachdem Ihr den Inhalt überflogen habt, wird Euch klar, dass der Verfasser des Buchs die Person sein muss, die für die übermäßig aggressiven Plünderer hier verantwortlich ist.\n\nEine Karte auf der Rückseite des Umschlags zeigt, dass der Verfasser einen Bunker in der südwestlichen Region von Uldum besitzt.\n\nVielleicht wäre es angebracht, sich einmal vorzustellen.", sourceObjective = "Bringt 'Effiziente Ausgrabungen' zu Bellok Leuchtklinge in Schnottz' Landeplatz.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[29810] = { id = 29810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gesichtslosen", description = "Jedes Mal, wenn mein Volk im Kampf gegen die Streitkräfte der Untoten an Boden verlor, grub es tiefer. In seiner Verzweiflung grub es zu tief.\n\nVersehentlich legten wir dabei ein Stück des Alten Gottes frei, das sich in Kreaturen manifestierte, die wir die Gesichtslosen nennen.\n\nAm Ende konnten wir solch mächtige Feinde nicht gleichzeitig an zwei Fronten bekämpfen. Unser Pech kostete uns den Krieg gegen die Untoten und schließlich auch unsere Heimat.\n\nBetretet Ahn'kahet, {class} und befreit unsere ehemalige Heimat von diesen gesichtslosen Monstrositäten.", sourceObjective = "Kilix der Entwirrer in der Grube von Narjun möchte, dass Ihr Herold Volazj und die drei Vergessenen an seiner Seite in Ahn'kahet tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29811] = { id = 29811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Talisman des Torwächters", description = "Krik'thir, Wächter der Tore von Azjol-Nerub, war kein Verräter.\n\nEr fiel im Krieg der Spinne, als er unsere Heimat gegen die Geißel verteidigte.\n\nWie es seiner Stellung gebührte, besaß er den Schlüssel zum verborgenen Reich. Ich möchte, dass Ihr ihn bergt, damit er seinem Volk überbracht werden kann.", sourceObjective = "Pionier A'zak in Azjol-Nerub möchte, dass Ihr den Talisman des Torwächters von Krik'thir dem Torwächter erbeutet.", progress = "Wurde Krik'thirs Geist vom Fluch des Untodes befreit? Was ist mit dem Talisman?", completion = "Ich hatte es geahnt.\n\nEin Großteil des Reiches ist seit Krik'thirs letztem Kampf verschlossen geblieben. Vielleicht hat mein Volk die Tiefen bereits gesichert und wartet nur auf seine Befreiung. Vielleicht sind es jedoch auch die Gesichtslosen, die hinter verschlossenen Türen lauern.\n\nWir werden es irgendwann erfahren. Zuerst muss jedoch der freigelegte obere Teil von Azjol-Nerub von Arthas' Schmutz gesäubert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29812] = { id = 29812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Kuscheltiere", description = "Das Fuchswäldchen ist für die hiesigen roten Pandas zu einem gefährlichen Ort geworden.\n\nLeider haben die Füchse des Wäldchens dank meiner Unterstützung des verrückten Braumeisters Schattenschenk einen berauschenden Biss entwickelt. Dieser macht die kleinen roten Pandas betrunken, sodass sie sich nicht mehr wehren können.\n\nBitte! Könnt Ihr mir helfen?\n\nWenn Ihr einige von ihnen zusammentreibt, kann ich dieses Feuer mit einem Geruch versehen, der sie ausnüchtert. Dann dürften sie wenigstens für eine Weile in Sicherheit sein.", sourceObjective = "Fangt 5 betrunkene rote Pandas im Fuchswäldchen mit dem Lasso und bringt sie zu Lehrling Ji Bierbrunst.", sourceObjectiveStatus = "unverified-source-field" }
quests[29813] = { id = 29813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tödliche Katerstimmung", description = "Ich hab ihm gesagt, er soll das lassen!  Aber \"niemand stellt sich Braumeister Schattenschenk in den Weg\".\n\nMein Meister ging und vergiftete die örtliche Wasserversorgung, weil er versuchte, dem Wasser \"Geschmack zu verleihen\". Das Gift tröpfelte bis hier hinunter zum Fuchswäldchen, wo das Gebräu eine bleibende Wirkung auf die Füchse hat.\n\nEs verdreht ihren Geist und lässt sie in Raserei verfallen. Jetzt sind sie eine ständige Gefahr für alle Reisenden und das hier ansässige Wildleben.\n\nKönnt Ihr mir bitte helfen, eine nennenswerte Anzahl von ihnen zu erlegen?", sourceObjective = "Tötet 8 betrunkene Füchse im Fuchswäldchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29814] = { id = 29814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jäger gesucht", description = "Wie es scheint, hat mein Meister den gesamten Wasservorrat mit seinem Geschmacksexperiment vergiftet.\n\nIch habe möglicherweise ein Gegenmittel, aber ich brauche dafür Nachschub. Bei leichteren Fällen fanden meine Leute, dass Orchideen ein wunderbares Heilmittel sind.\n\nBesiegt die Orchideenjäger im Orchiswinkel und sammelt einige der bestäubten Orchideen, die sie bei sich tragen. Wir werden sie zur Reinigung der zentralen Wasserquellen verwenden.", sourceObjective = "Besiegt Orchideenjäger und bringt 15 der bestäubten Orchideen, die sie hervorbringen, an Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[29815] = { id = 29815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forensische Wissenschaft", description = "Diese Kreaturen sind überall - und aggressiv sind sie noch dazu! Wir müssen uns um sie kümmern, bevor noch mehr Allianzmitglieder hier auftauchen.\n\nDieses Exemplar hier ist ziemlich übel zugerichtet, aber ich konnte dennoch einige Erkenntnisse über seine Anatomie gewinnen.\n\nMit den richtigen Reagenzien sollte es mir gelingen, ein Gift zusammenzubrauen, das im Kampf gegen diese Spezies seine Wirkung nicht verfehlen wird. Es sollte sogar reichen, einfach das Gift, das ich bei mir trage, etwas zu modifizieren.\n\nZieht los und sucht mir in der Nähe des Wassers etwas Zähflüssiges Chlorophyll. Jedes halbintelligente Pflanzenwesen dürfte den Zweck erfüllen.", sourceObjective = "Sammelt 8 Einheiten zähflüssiges Chlorophyll.", progress = "Ich hoffe, Ihr hattet Erfolg. Unser Überleben hier hängt vielleicht davon ab.", completion = "Oh, ja, {name}. Damit kann ich etwas anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29816] = { id = 29816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt eine Probe", description = "Es wird Zeit, dass der verrückte Braumeister sein eigenes Gift zu schmecken bekommt.\n\nIm Osten gibt es einige Pandaren, die einer beinahe tödlichen \"Geschmacksprobe\" von Schattenschenk beigewohnt haben.\n\nKönnt Ihr Euch in das Tal begeben und nachsehen, ob von dem, was sie gestern Abend probiert haben, noch etwas übrig ist? Wenn Ihr genug Proben zusammenbekommt, kann ich versuchen, sein Gebräu nachzumachen.\n\nGebt meinem Freund Jian die Proben. Er sollte in der Lage sein, sie ein wenig abzuändern.\n\nOh - und seid vorsichtig. Scheinbar hat sein Getränk einige verabscheuungswürdige Nebenwirkungen.", sourceObjective = "Nehmt 8 Toxinproben von besoffenen Pandaren an Euch und bringt sie zu Jian im Tal des Verrückten Braumeisters.", sourceObjectiveStatus = "unverified-source-field" }
quests[29817] = { id = 29817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrunkene Tiger", description = "Orchideen mögen für mein Volk ein Heilmittel sein, doch für die einheimischen Tiger sind sie eine intensive Droge. Diese Tiere werden oft von den Orchideenfeldern und der berauschenden Wirkung, die die Blumen auf sie haben, angezogen.\n\nWenn Ihr die Toxine, die Schattenschenk dem Wasser hinzugefügt hat, noch hinzurechnet, führt das zu sehr gefährlichen und rasenden Tieren. Es wird nicht lange dauern, bis sie den Jadetempel bedrohen. \n\nKönnt Ihr sie bitte dezimieren?", sourceObjective = "Tötet 9 tollwütige Tiger im Orchiswinkel.", sourceObjectiveStatus = "unverified-source-field" }
quests[29818] = { id = 29818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage des Geschmacks", description = "Mit diesen Orchideen, die Ihr uns gebracht habt, können wir vielleicht das größere Problem lösen.\n\nIm Tal östlich von hier liegt der See, der von Braumeisters Schattenschenk kontaminiert wurde. Begebt Euch dorthin, werft diese Kräuter hinein und lockt so die Kreaturen hervor, die Ihr dann vernichten müsst.\n\nSprecht mit meinem Freund Jian, wenn Ihr dies erledigt habt. Er ist ein freundlicher Wassergeist, der dem Braumeister und mir geholfen hat, ein paar Rezepte herzustellen.", sourceObjective = "Verwendet die reinigenden Orchideen am Seeufer im Tal des Verrückten Braumeisters und besiegt dann die Kreaturen, die Ihr damit hervorlockt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29819] = { id = 29819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der neue Meister", description = "Jetzt hab' ich's! Mit den Giftstoffen, die Ihr besorgt habt, konnte ich nicht nur das Rezept vom Schattenschenk nachvollziehen, sondern auch sein Problem lösen, das diese Krankheit hervorgerufen hat.\n\nWisst Ihr, was das bedeutet? Jede Menge Geschmack und keine tödlichen Nebenwirkungen!\n\nUnd jetzt kümmern wir uns um den Braumeister. Ich habe Kalki mit einigen Proben beladen. Könnt Ihr sie zu Schattenschenk bringen, um ihn zu einem Verkostungsduell herauszufordern?\n\nIhr werdet mit seinen Gebräuen konfrontiert werden, aber mit meinem ausnüchternden Feuer werdet Ihr Euch durchschummeln können.", sourceObjective = "Begebt Euch zur Arena der Verkoster und fordert den Braumeister Schattenschenk zu einem Verkostungsduell heraus.", sourceObjectiveStatus = "unverified-source-field" }
quests[29820] = { id = 29820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinein in den Nexus", description = "Ich habe Kriegsmagierin Kaitlyn in den Nexus geschickt, damit sie Malygos' chaotisches Reich untersucht, aber sie hat sich seit Tagen nicht gemeldet.\n\nKönntet Ihr dorthin gehen und sie unterstützen? Sie könnte sicherlich Hilfe gebrauchen, wenn die Drachen sie nicht schon gefressen haben.", sourceObjective = "Erzmagier Berinand hat Euch gebeten, mit Kriegsmagierin Kaitlyn im Nexus zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29821] = { id = 29821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miese kleine Diebe", description = "Hör mal, <Kumpel/Schätzchen>.\n\nIch hab ein paar Versorgungsdrohnen vom Luftschiff aus losgeschickt, aber die sind alle abgestürzt oder verloren gegangen. Na ja, fast alle.\n\nEine von ihnen ist hier durchs Lager gesurrt und dann bei den Wasserfällen abgeschmiert.\n\nWarum schaut Ihr nicht mal, ob Ihr die Inhalte dieser Kiste retten und hierherbringen könnt, hmm?\n\nWir haben zwar keine Drohnen mehr, aber meine Raketenstiefel könnten hier ganz nützlich sein. Die gehen ab wie eine - na? - Rakete!\n\nHa ha, ich lach mich schief...", sourceObjective = "Findet die fehlende Vorratskiste bei der Kaskade der Ruhe.\n\nBereitgestellter Gegenstand:", completion = "Diese Kiste sollte voller Vorräte sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[29822] = { id = 29822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eigenheiten des Landes", description = "Diese verfluchten Fellknäuel! Für jeden von ihnen, den wir töten, stehen plötzlich zwei neue da...\n\nNichts hat sich geändert, {name}. Befehle sind Befehle, egal, wie wenige wir sind und wie schlecht unsere Chancen stehen.\n\nIch muss Pläne schmieden und Probleme lösen.\n\nZieht in das Land und lernt seine Eigenheiten kennen. Kommt erst wieder, wenn Ihr etwas Nützliches zu berichten habt.\n\nUnd wenn Ihr unterwegs seid, seht zu, dass dieser jammernde Idiot die Klappe hält! Weggetreten!", sourceObjective = "Besucht den Schrein der Sonne, den Schrein des Mondes und tötet Djuuk Uukem.", completion = "Willkommen, Reisender.\n\nBitte, macht es Euch bequem.", sourceObjectiveStatus = "unverified-source-field" }
quests[29823] = { id = 29823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherbericht: Der Freund meines Feindes", description = "Wisst Ihr, wir haben nicht nur nach der Allianz gesucht. Wir haben auch nach diesen watzrommeligen, flipmippischen Jinyu gesucht!\n\nNa ja, wir ha'm sie ja auch gefunden...", sourceObjective = "Hört Euch Rikos Bericht an.", completion = "Ja, ich bin weggelaufen. Na und? Ohne mich wäre Kiryn jetzt tot. Oh, Moment… sie ist bereits tot… bereits...\n\nGeht weg! Riko hat Kopfschmerzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29824] = { id = 29824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherbericht: Butter bei die Jinyu", description = "Nachdem unser Anführer in Jade verwandelt wurde, unser Ho-zen-Führer verschwunden war und wir einen Kriegsgefangenen im Schlepptau hatten, blieb nur eins für Kiryn und mich zu tun:\n\nIns Feindesland einmarschieren und Rache nehmen.\n\nWollt Ihr wissen, wie das gelaufen ist?", sourceObjective = "Hört Euch Shokias Bericht an.", completion = "Das Wichtigste, das wir lernten, war... dass die Allianz nicht nur Freundschaft mit den Jinyu geschlossen hat, sondern sie auch mit Waffen versorgt und ihnen beibringt, wie man sie benutzt.\n\nDie Allianz hat jetzt eine Armee, die uns dreißig-zu-eins zahlenmäßig überlegen ist. Und wir - die HORDE - haben Freundschaft mit Affen geschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29825] = { id = 29825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht länger ein Schüler", description = "Einst nannte ich Urahne Nadox meinen Lehrer.\n\nDas änderte sich für immer, als ich zusehen musste, wie er, ein Diener der Verdammten, meine Freunde und meine Familie umbrachte.\n\nFindet ihn in den Tiefen und sorgt dafür, dass er für seine Verbrechen bezahlt.", sourceObjective = "Seher Ixit in Ahn'kahet hat Euch gebeten, Urahne Nadox zu töten.", progress = "Ist der mächtige Nadox endlich tot?", completion = "Ich hoffe, dass ich nun an Nadox' Stelle treten und mein Volk anführen kann.\n\nDas Reich von Azjol-Nerub wird Großes vollbringen, {race}...", sourceObjectiveStatus = "unverified-source-field" }
quests[29826] = { id = 29826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung von Ahn'kahet", description = "Prinz Taldaram und seine Geißelarmee benutzen die gleichen Barrieren, hinter denen wir einst unser Reich verbargen, um sich vor den Einheimischen der eisigen Tiefen zu schützen.\n\nDeaktiviert die Barrieren und tötet die Geißelsoldaten, die sie bewachen. Meine Streitkräfte werden zusammen mit den Einheimischen den Rest erledigen.", sourceObjective = "Seher Ixit in Ahn'kahet möchte, dass Ihr 3 Augen von Taldaram, einen Knochenschinder und Prinz Taldaram tötet.", progress = "Auch lange nach der Niederlage der Geißel werden wir noch viel in Ahn'kahet zu tun haben.", completion = "Hervorragend.\n\n<Ihr hört einige klickende Geräusche.>\n\nUnd nun zu unserem anderen Feind...", sourceObjectiveStatus = "unverified-source-field" }
quests[29827] = { id = 29827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saurer Regen", description = "Während Ihr fort wart, haben sich immer mehr von diesen Kreaturen in der Nähe unseres Lagers versammelt. Sie scheinen eine Großoffensive vorzubereiten!\n\nWir werden drastische Mittel ergreifen müssen, wenn wir nicht sang- und klanglos untergehen wollen.\n\nHier, nehmt meine vergifteten Wurfsterne und überlegt Euch, wie Ihr ihre Reihen etwas dezimieren könnt.", sourceObjective = "Benutzt den Geborgenen Gyrokopter, um 25 Ho-zen-Magenfetzer und 25 Ho-zen-Spenkspieker zu töten.", progress = "Nun, {name}? Werden wir noch einen weiteren Tag erleben?", completion = "Ausgezeichnet! Welch kreative Lösung!\n\nDas sollte sie eine Weile fernhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29828] = { id = 29828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Alptraum der Geißel", description = "Ein flüchtender Drakkaritroll hat mir von einem großen Raptorkönig namens Dred erzählt, der gegen die Seuche immun ist.\n\nFindet diesen König Dred und bringt mir einen seiner Zähne. Vielleicht kann ich daraus eine Waffe herstellen.", sourceObjective = "Kurzel in der Feste Drak'Tharon möchte, dass Ihr König Dred tötet und ihr seinen Zahn bringt.", progress = "Gibt es diese gewaltige Bestie wirklich?", completion = "<Kurzels Augen weiten sich.>\n\nBoah! Der ist ja riesig!", sourceObjectiveStatus = "unverified-source-field" }
quests[29829] = { id = 29829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diskretion ist der Schlüssel", description = "Hört mir zu, {race}.\n\nMir wurde soeben mitgeteilt, dass sich in der Violetten Festung ein Zwischenfall ereignet hat. Es scheint, als würde der blaue Drachenschwarm eine groß angelegte Invasion Dalarans vorbereiten!\n\nIch möchte, dass Ihr Euch umgehend zum Gefängnis begebt und mit Leutnant Sinclari sprecht. Sie wird Euch alles erklären.\n\nDoch das ist nicht alles. Ihr müsst äußerst diskret vorgehen. Wir dürfen die Bürger Dalarans nicht verunsichern, wenn es sich vermeiden lässt. Habe ich mich klar ausgedrückt?\n\nGut. Dann geht jetzt.", sourceObjective = "Rhonin möchte, dass Ihr zur Violetten Festung in Dalaran geht und mit Leutnant Sinclari sprecht.", completion = "Keinen Augenblick zu früh.\n\nSeid Ihr bereit, Dalaran zu verteidigen, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[29830] = { id = 29830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindämmung", description = "Meine Streitkräfte liegen am Boden, aber Malygos' Angreifer stürmen immer weiter auf uns ein.\n\nIhr müsst sie aufhalten, bis ihre Anführerin Cyanigosa auftaucht. Nur ihr Tod wird die Invasion beenden und Dalaran retten.\n\nSprecht mich an, wenn Ihr bereit seid.", sourceObjective = "Leutnant Sinclari in der Violetten Festung möchte, dass Ihr die Invasion der blauen Drachen aufhaltet. Sprecht mit ihr, wenn Cyanigosa geschlagen ist.", progress = "Ist es vorbei? Konntet Ihr dem Angriff standhalten?", completion = "Danke, mein Held!\n\nDank Eures Mutes konnte Dalaran einen weiteren Tag überstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29833] = { id = 29833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offene Rechnungen", description = "Der Prophet von Akali mag diese Welt zwar nicht mehr belästigen, doch es gibt noch immer Arbeit zu tun.\n\nAkalis Blut - ein Großteil davon - hat jemand anderem Macht verliehen und es ist dieser jemand, von dem die eigentliche Gefahr ausgeht.\n\nSchnell, {name}, macht Euch auf den Weg nach Gundrak und sprecht mit Tol'mar. Er wird Euch diesbezüglich weitere Anweisungen geben können.", sourceObjective = "Har'koa möchte, dass Ihr mit Tol'mar in Gundrak sprecht.", completion = "Hör zu, Mann. Die Arbeit, die hier erledigt werden muss, is' gefährlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[29834] = { id = 29834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gal'darah muss bezahlen", description = "War das schlimmste, was ich je gesehen hab', Mann. Der große Akali - vor meinen Augen getötet. Furchtbar...\n\nIch bin nur hier, um zu beobachten, aber so was geht nich'! Gal'darah un' seine Anhänger müssen dafür bezahlen!\n\nRäche Akalis Tod, Mann. Muss sein.", sourceObjective = "Tol'mar möchte, dass Ihr Slad'ran, Moorabi und Gal'darah in Gundrak tötet.", completion = "Du hast es getan?! Sie sind hin?\n\nHier, Mann. Das Geschenk is' für dich, weil du den Eisigen Weiten Gerechtigkeit gebracht has'.", sourceObjectiveStatus = "unverified-source-field" }
quests[29835] = { id = 29835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gal'darah muss bezahlen", description = "Der mächtige Akali is' tot, {race}.\n\nMeine Rolle im Leben ist es, Dinge aufzuzeichnen, nich' zu kämpfen. Aber das geht nicht! Gal'darah und seine Anhänger müssen bezahlen!\n\nRäche Akalis Tod, Mann. Muss sein.", sourceObjective = "Chronistin Bah'Kini möchte, dass Ihr Slad'ran, Moorabi und Gal'darah in Gundrak tötet.", completion = "Du hast es getan?\n\nDamit hast du meine Erwartungen voll übertroffen, Mann. Das Geschenk is' für dich, weil du den Eisigen Weiten Gerechtigkeit gebracht has'.", sourceObjectiveStatus = "unverified-source-field" }
quests[29836] = { id = 29836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur ma' nachsehen", description = "Unten aus Gundrak waren fürchterliche Geräusche zu hören. In letzter Zeit sind sie lauter geworden und auch häufiger zu hören.\n\nMeine langjährige Schülerin konnte von ihrem Posten westlich von Gundrak aus die Ereignisse erfassen. Hättet Ihr vielleicht Zeit, bei Ihr nachzusehen, was los ist?", sourceObjective = "To'kini möchte, dass Ihr mit Bah'Kini in Gundrak sprecht.", completion = "To'kini is' mein feiger Vater – er traut sich nicht so nahe an Gundrak heran... deshalb hat er mich geschickt!\n\nHier gibt's so viel Trollgeschichte. Wir dürf'n nich' zulassen, dass Gal'darah un' seine irren Anhänger sie auf ewig vor uns verstecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[29837] = { id = 29837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilige Schriftrolle", description = "Die fremdartigen Markierungen auf diesem Pergament haben eine Eleganz an sich, zu der dieser Yoggtord und seine Bande gar nicht fähig wären.\n\nIhr vermutet, dass es wie alles andere auch, was diese Ho-zen besitzen, gestohlen ist.\n\nMöglicherweise hält sich der rechtmäßige Besitzer der Schriftrolle noch in der Nähe auf...", sourceObjective = "Bringt die unlesbare Schriftrolle zu Lehrensucher Cho.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[29838] = { id = 29838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzigartig", description = "Auf'n ersten Blick denkt ma', die Geschichte kenn' ich schon: Trolle zapf'n verbotene Energien an, weil sie die Wesen vernicht'n, die sie eigentlich anbeten sollt'n.\n\nWenn's stimmt, was ich so hör', dann haben sie 'nen besonderen Golem - einen, der anders is' als alle andren vor ihm!\n\nBring mir'n Stück von dem Golem zum Untersuchen, Mann.", sourceObjective = "Chronistin Bah'Kini möchte, dass Ihr ein Stück des Kolosses der Drakkari in Gundrak erbeutet.", progress = "Hast du mir ein Stück dieses Golems gebracht, Mann?", completion = "Ahh, ja Mann! Das ist es, wonach ich gesucht habe.\n\nHier, bitte schön - nimm dir was Schönes für den Ärger, den du hattest.", sourceObjectiveStatus = "unverified-source-field" }
quests[29839] = { id = 29839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzigartig", description = "Dem ganz'n Ärger hätte man aus'm Weg gehen können, wenn die Drakkari die Götter angebetet, anstatt umgebracht hätt'n.\n\nIch hab gehört, dass sie 'nen besonderen Golem haben, einen, in dem verbotene Energien stecken.\n\nBring mir ein Stück von dem Golem, Mann, damit wir von uns'ren Brüdern und Schwestern lernen können.", sourceObjective = "Tol'mar möchte, dass Ihr ein Stück des Kolosses der Drakkari in Gundrak erbeutet.", progress = "Hast du den Golem gefunden, Mann? Der muss da irgendwo sein.", completion = "Unglaublich! Sowas hab' ich noch nie geseh'n.\n\nGute Arbeit, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[29840] = { id = 29840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Nachwelt", description = "Gundrak is' nich' mehr zu rett'n, Mann. Du weißt, dass ich Recht habe.\n\nWenn du den Mut dazu hast, such nach Geschichtstafeln, in denen steht, wieso das Reich der Drakkari gefall'n is'.\n\nVielleicht könn'n wir's eines Tages wieder aufbau'n.", sourceObjective = "Chronistin Bah'Kini in Gundrak möchte, dass Ihr 6 Geschichtstafeln der Drakkari sammelt.", progress = "Haste die Geschichtstafeln der Drakkari gefund'n, Mann?", completion = "Bin dir echt dankbar dafür, Mann.\n\nDie werd'n uns 'ne große Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[29841] = { id = 29841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschaffenheit des Landes [TEMP]", description = "Grah!!\n\nFür jeden dieser Schlammschleuderer, den wir ausschalten, springen zwei weitere aus dem Wald und nehmen seinen Platz ein. Ich möchte nicht, dass die anderen es schon erfahren, aber es ist offensichtlich, dass wir hier nicht lange durchhalten werden, {name}.\n\nIch muss hier bleiben und unseren letzten Besitz verteidigen. Erkundet Ihr die Gegend und sucht eine Lösung für unser Primatenproblem.\n\nGeht jetzt. Unsere Hoffnungen begleiten Euch...", sourceObjective = "Erkundet die Gegend.", sourceObjectiveStatus = "unverified-source-field" }
quests[29842] = { id = 29842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antworten suchen", description = "<Cho hört sich zuerst Eure Fragen an, bevor er spricht.>\n\nSo viel, über das man nachdenken muss, <Reisender/Reisende>...\n\nIhr müsst zuerst lernen, wie man fragt, bevor Euer Geist die Wahrheit erkennen kann.\n\nIch habe meine Meditation für heute beendet, aber meine Kerzen bleiben am Ring des Blutes.\n\nGeht dorthin. Leert Euren Geist. Wir sprechen uns wieder, wenn Ihr bereit seid, meine Worte zu hören.", sourceObjective = "Nutzt die Kerzen, um am Cairn des Blutes zu meditieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[29843] = { id = 29843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tantchen Lin Windpelz", description = "Sobald alles organisiert ist, kehren wir in die Stadt zurück. Niemand kommt mir jetzt in die Quere! Der kriegt einen Tritt an den Kopf! Danach habe ich bestimmt meine Ruhe.\n\nVielen Dank für Eure Hilfe. Könnt Ihr Tantchen Lin in Pandastadt sagen, dass es uns gut geht und dass wir auf dem Rückweg sind? Sie besitzt sehr viele schöne Sachen, die sie Euch vielleicht als Belohnung gibt.", sourceObjective = "Sprecht mit Lin Windpelz in Pandastadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29844] = { id = 29844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Nachwelt", description = "Das Land der Eistrolle is' nur noch'n Schatten seiner selbst.\n\nWenn du genug Mut aufbringst, dann such doch mal nach Geschichtstafeln, Mann. Da steht drin, wieso das Reich der Drakkari untergegang'n ist.\n\nEines Tages werd'n wir das Land vielleicht an 'ne neue Generation Frosttrolle weitergeb'n können.", sourceObjective = "Tol'mar in Gundrak möchte, dass Ihr 6 Geschichtstafeln der Drakkari sammelt.", progress = "Haste die Geschichtstafeln der Drakkari gefund'n, Mann?", completion = "Die Reiche von uns Trollen werd'n schon länger gespalten als es die andren Völker gibt, Mann.\n\nWir steh'n immer wieder aus den Ruinen auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[29847] = { id = 29847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Spuren des Diebs", description = "Unmittelbar hinter dieser Höhle liegt das Rabenholdtanwesen. Ihr müsst dort eindringen, ohne bemerkt zu werden!\n\n<Mostrasz belegt Euch mit einer Verzauberung.>\n\nGut - nun kann ich Euch auf Eurem Weg durch das Anwesen beobachten und mit Euch kommunizieren. Schleicht Euch hinein, findet das Ei und lasst Euch nicht erwischen...", sourceObjective = "Dringt in das Rabenholdtanwesen ein und findet das verschwundene Schwarzdrachenei.", completion = "Werdet Ihr mit mir zusammenarbeiten?\n\nGut. Sehr gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[29848] = { id = 29848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Behüterin", description = "Ich würde mein Leben mit Freuden für die Schöpfer oder ihre Wesen hingeben.\n\nSeit Lokens Verrat scheint es mir jedoch, als habe sich ganz Ulduar gegen die Welt verschworen. Vor allem die Maid der Trauer leidet entsetzlich unter ihren neuen Befehlen.\n\nBitte schenkt ihr Frieden und bringt mir eine ihrer Tränen.", sourceObjective = "Kaldir Eisenbann in den Hallen des Steins möchte, dass Ihr der Maid der Trauer Frieden schenkt und eine Kristallträne der Trauer beschafft.", progress = "Ich wünschte, es gäbe einen anderen Weg, aber nur der Tod kann die Maid jetzt noch erlösen.", completion = "<Kaldir starrt einen Moment schweigend in den Kristall.>\n\nKein Wesen hat das Leid je so gespürt wie die Maid der Trauer.\n\nDaran sollten wir denken, während wir unseren Kampf gegen Loken fortsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29850] = { id = 29850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrupte Konstrukte", description = "Die Eisenzwerge haben damit begonnen, gewaltige Steinkonstrukte zu erschaffen, die sie, so fürchte ich, bald als mächtige Waffen einsetzen werden.\n\nIhr müsst unbedingt ihren Aufseher Krystallus und die dunklen Runenriesen, die bereits in den Hallen aufgetaucht sind, besiegen. Beeilt Euch, bevor es zu spät ist!", sourceObjective = "Kaldir Eisenbann in den Hallen des Steins möchte, dass Ihr Krystallus und 3 dunkle Runenriesen tötet.", completion = "Gut gemacht, {race}.\n\nJede Waffe, die wir Loken abnehmen können, hilft unserem eigenen Feldzug.", sourceObjectiveStatus = "unverified-source-field" }
quests[29851] = { id = 29851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion des Turniers", description = "Dank dieses Turniers kommen wir unserer letzten Konfrontation mit dem Lichkönig immer näher.\n\n{name}, kämpft tapfer und ehrenhaft. Die Kämpfer hier haben sich hier zu unser aller Wohl versammelt.\n\nGemeinsam werden wir Arthas aufhalten!", sourceObjective = "Hochlord Tirion Fordring hat Euch beauftragt, die Prüfung des Champions zu vollenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29853] = { id = 29853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion des Königs", description = "Dank dieses Turniers kommen wir unserer letzten Konfrontation mit dem Lichkönig immer näher.\n\n{name}, Ihr werdet die Allianz in dieser großen Arena repräsentieren.\n\nBeweist Euch gegen die besten Kämpfer von Azeroth. Kämpft ehrenhaft.", sourceObjective = "König Varian Wrynn hat Euch beauftragt, die Prüfung des Champions zu vollenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29856] = { id = 29856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cairn der Knochen", description = "Euer Geist war klar.\n\nIhr dachtet, Ihr wäret konzentriert.\n\nVielleicht war es das ständige Brummen der Insekten, das Euch einschlafen ließ. So muss es gewesen sein!\n\nAus dem Augenwinkel seht Ihr eine weitere Steinformation, genau nördlich von hier.\n\nVielleicht ist es dort ruhiger...", sourceObjective = "Benutzt die Meditationskerze am Cairn der Knochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29858] = { id = 29858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weisheit des Alters", description = "Ihr müsst lernen, die Prüfungen Eures Lebens mit Demut und Unvoreingenommenheit anzugehen, <Fremder/Fremde>.\n\nWeisheit passt nicht durch die engen Schlitze der Augen eines Skeptikers.\n\nSucht mich am Cairn des Gesteins auf, und ich werde Euch die uralte Kunst der Meditation lehren.\n\nWenn Ihr erst einmal Euren Frieden gefunden habt, werden Euch die Antworten, die Ihr sucht, nicht mehr so fern erscheinen, wie Ihr möglicherweise glaubt.", sourceObjective = "Sprecht mit Lehrensucher Cho am Ring der Steine, um Meditation zu üben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29860] = { id = 29860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegensätze", description = "Ich werde offen mit Euch sprechen, <kleiner/kleine:r> {race}. Mein Volk ist nicht mehr das gleiche, seit unsere Verbindung zu Thorim abgerissen ist.\n\nVolkhan wird nicht ruhen, bis er oder wir nicht mehr existieren. Wir wollen nur Frieden, doch es scheint, als läge unsere einzige Hoffnung im Krieg.", sourceObjective = "Sturmbote Eljrrin in den Hallen der Blitze möchte, dass Ihr Volkhan besiegt.", progress = "Wurde Volkhan ausgelöscht, kleiner {race}?", completion = "Volkhan wird mein Volk nicht mehr in seinen Träumen heimsuchen.\n\nMacht weiter wie bisher, kleiner {race}. Irgendwann wird mein Volk Thorim schon vergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29861] = { id = 29861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit allen Mitteln!", description = "Loken wird fallen, egal, wie.\n\nDie Ehre und der Ruhm seiner Niederlage soll Euch gebühren.\n\nKehrt zu mir mit seiner gespaltenen Zunge zurück und verdient Euch meinen ewigen Dank.", sourceObjective = "Sturmbote Eljrrin in den Hallen der Blitze möchte, dass Ihr Loken besiegt. Dann sollt Ihr mit Lokens Zunge zu Sturmbote Eljrrin zurückkehren.", progress = "Habt Ihr Gerechtigkeit über Loken gebracht?", completion = "Dieser widerliche Wurm ist tot?\n\nIhr seid wahrhaft ein Segen für mein Volk, kleiner {race}. Bitte nehmt dieses Geschenk als Anerkennung Eurer loyalen Freundschaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[29862] = { id = 29862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg frei machen", description = "Lokens Streitkräfte bereiten sich auf den Krieg vor. Sie rechnen allerdings nicht damit, selbst angegriffen zu werden.\n\nWir müssen rasch zuschlagen. Vernichtet General Bjarngrim und seine Armee, bevor sie alles Leben auf Azeroth gefährden!", sourceObjective = "Sturmbote Eljrrin in den Hallen der Blitze möchte, dass Ihr 3 sturmgeschmiedete Heiler, 3 sturmgeschmiedete Taktiker und General Bjarngrim tötet.", completion = "Nur wenige außer uns werden je davon erfahren, aber Ihr habt an diesem Tag die Welt gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29863] = { id = 29863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmbote Eljrrin", description = "Ich habe einen Abgesandten in die Hallen der Blitze geschickt, um Loken zu bedrängen.\n\nEr könnte zweifellos Hilfe gebrauchen, wenn man die Stärke von Lokens Armeen bedenkt. Unterstützt ihn so gut Ihr könnt, damit wir den Verräter endlich besiegen können.", sourceObjective = "König Jokkum möchte, dass Ihr die Hallen der Blitze betretet und mit Sturmbote Eljrrin sprecht.", completion = "Wir haben nicht viel Zeit. Loken bereitet sich bereits auf den Krieg vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[29864] = { id = 29864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wurzel des Übels", description = "Wir tun alles, um die Verluste, die uns die Kriegsmaschinerie der Geißel zufügt, zu minimieren.\n\nDie Vrykul gefährden diese Mission, indem sie sich willentlich den Truppen des Lichkönigs anschließen.\n\nBitte, <edler Held/edle Heldin>, besiegt ihre spirituelle Anführerin Svala, bevor sie ihr Volk in die ewigen Schatten führt!", sourceObjective = "Argentumbeichtpatin Blondlocke möchte, dass Ihr Svala Grabesleid tötet.", progress = "Ich vertraue auf Euch, {name}.", completion = "Jeder Soldat, den wir der Geißel vorenthalten, bedeutet mehr als nur ein gerettetes Leben.\n\nDanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[29865] = { id = 29865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seidenwaldstraße", description = "Westlich von hier befindet sich die Seidenwaldstraße. Es ist mittlerweile sehr gefährlich, sie zu bereisen, weil die Spinnen dort immer bösartiger, um nicht zu sagen \"gefräßiger\", geworden sind.\n\nIch würde sie ja herzlich gern selbst ausrotten, aber jemand muss ja den Nudelladen... öh... verteidigen...\n\nAlso, <junger Held/junge Heldin>, geht und zerquetscht diese Biester! Wenn Ihr Erfolg habt, werde ich Euch vielleicht mit einer meiner Heldensagen belohnen.\n\nUnd mit einer Bezahlung, versteht sich.", sourceObjective = "Zerquetscht 8 Seidenholzpirscher.", completion = "Was für ein edler Held Ihr doch seid. Ihr erinnert mich an mich selbst, als ich noch jünger und weniger gut aussehend war.", sourceObjectiveStatus = "unverified-source-field" }
quests[29866] = { id = 29866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seidenernte", description = "Ah, willkommen, <Reisender/Reisende>. Ich würde gern Eure Dienste in Anspruch nehmen!\n\nSyra Zapfgold ist auf der Suche nach etwas Seide. Ich selbst hasse ja Seide, weil sie sich immer in meinem Fell verfängt.\n\nAber ich möchte sie wirklich gern beeindrucken.\n\nWenn Ihr mir etwas Seide aus dem Seidenwald westlich von hier bringen könnt, werde ich Euch gerne dafür bezahlen.", sourceObjective = "Sammelt 7 makellose Seidenstränge.", progress = "Habt Ihr den Seidenwald gefunden?", completion = "Oh, vielen herzlichen Dank! Die sind perfekt!\n\nIch hoffe, Ihr habt Euch nicht so darin verfangen wie ich sonst immer.\n\nIch werde jetzt gleich zu Syra gehen und sie ihr geben!", sourceObjectiveStatus = "unverified-source-field" }
quests[29869] = { id = 29869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Klatschen einer Hand", description = "Ihr müsst noch viel lernen, aber Ihr befindet Euch zumindest schon auf dem Weg zur Erleuchtung.\n\nDenkt daran, was ich Euch gelehrt habe, und wendet Euer Wissen am See im Westen an.\n\nMit Geduld und Übung können Harmonie und Erleuchtung erreicht werden. Dann wird echte Weisheit den Weg in Euren Verstand finden.\n\nAußerdem seid Ihr dann weit genug weg von hier, dass mich Euer Schnarchen nicht mehr beim Studieren stört.\n\nLebt wohl, <Fremder/Fremde>.", sourceObjective = "Meditiert am Cairn der Schuppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29871] = { id = 29871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schlaue Ashyo", description = "Ich weiß nicht, wo der schlaue Ashyo den Titel \"schlau\" herhat. Alle Jinyu sind nämlich schlau, und ich würde nicht behaupten, dass er klüger als die meisten anderen ist.\n\nEigentlich ist das Gegenteil der Fall.\n\nZumindest ist er ein fähiger Kämpfer. Im Tiankloster war er gut genug, um für unsere Trainingsmission ausgewählt zu werden.\n\nWenn Ihr ihm bei der Suche nach dem verborgenen Meister helfen wollt, findet Ihr ihn an der nördlichen Grenze des Tals.", sourceObjective = "Findet den schlauen Ashyo.", completion = "Wo habe ich Euch schon einmal gesehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29872] = { id = 29872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lin Zartpfote", description = "Lin hat mehr Talent, als sie selbst glaubt. Sie hat eine starke Faust, aber einen schwachen Geist. Mit etwas mehr Selbstvertrauen könnte sie besser sein als wir alle.\n\nVielleicht gewinnt sie bei ihrer Reise in den Westen an Selbstsicherheit. Wahrscheinlich ist sie gerade jetzt unterwegs nach Steinpflug. Haltet sie auf und redet mit ihr, wenn Ihr in jenem Teil des Tals seid.", sourceObjective = "Findet Lin Zartpfote.", completion = "Oh, Ihr seid es!\n\nNein, ich habe den verborgenen Meister noch nicht gefunden. Wahrscheinlich habe ich hier draußen nur meine Zeit vergeudet.\n\n<Seufz...>", sourceObjectiveStatus = "unverified-source-field" }
quests[29873] = { id = 29873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ken-Ken", description = "Ahso... Ken-Ken. Der Ho-zen.\n\nIch selbst bin beeindruckt, dass er in seiner Ausbildung so weit gekommen ist. Er hat ein Hirn zwischen den Ohren, was mehr ist, als man über die meisten seines Volks sagen kann.\n\nEr sagte, er wollte Richtung Osten, und da wir bereits weit im Osten des Tals sind, kann ich mir nicht vorstellen, dass er allzu weit von hier entfernt sein kann. Sucht nach ihm bei Zhus Wacht in der Krasarangwildnis, den Weg runter in Richtung Süden. Seht nach, was er gefunden hat.", sourceObjective = "Sucht Ken-Ken.", completion = "Dieser Ort... er... er so TRAURIG!\n\nKen-Ken noch nie einen so traurigen Ort gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29874] = { id = 29874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kang Dornstab", description = "Kangs Stolz wird regelmäßig zu Vermessenheit, was ihn oft auf gefährliche Pfade führt. Sein momentaner Pfad ist eben solch ein gefährlicher - er führt tief in die Krasarangwildnis.\n\nIch würde normalerweise <einen Fremden/eine Fremde> nicht um einen Gefallen bitten, aber... würdet Ihr Euch vergewissern, dass es ihm gut geht? Es wäre eine Erleichterung für mich, zu wissen, dass <ein mutiger/eine mutige:r> {race} nach ihm sieht.", sourceObjective = "Sucht Kang Dornstab.", completion = "Ich bin ziemlich sicher, dass diese Siedlung vor ein paar Wochen noch nicht hier war. Wo sind diese Leute hergekommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29875] = { id = 29875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kang Dornstab", description = "Kangs Stolz wird regelmäßig zu Vermessenheit, was ihn oft auf gefährliche Pfade führt. Sein momentaner Pfad ist eben solch ein gefährlicher - er führt tief in die Krasarangwildnis.\n\nIch würde normalerweise <einen Fremden/eine Fremde> nicht um einen Gefallen bitten, aber... würdet Ihr Euch vergewissern, dass es ihm gut geht? Es wäre eine Erleichterung für mich, zu wissen, dass <ein mutiger/eine mutige:r> {race} nach ihm sieht.", sourceObjective = "Sucht Kang Dornstab.", completion = "Ich bin ziemlich sicher, dass diese Siedlung vor ein paar Wochen noch nicht hier war. Wo sind diese Leute hergekommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[29877] = { id = 29877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundwissen mangelhaft", description = "Shed-Ling - die tun mehr, als nur unsere Nahrung fressen. Die wollen ihre eigenen Höfe gründen. Das Problem is' nur... Das sind alle verfiddelt taube Nüsse.\n\nDu glaubst Muno nicht? Gestern Nacht sind sie in unsere Werkzeugschuppen eingebrochen... ha'm das meiste rausgeklaut. Als wir aufgewacht sind, fanden wir Harken und Schubkarren im Boden.\n\nDie wollten das BEWÄSSERN. Die wollten SCHUBKARREN ANBAUEN.\n\nBitte grabe unsere Sachen aus, wenn du dort draußen bist.", sourceObjective = "Grabt 7 Landwirtschaftswerkzeuge aus.", progress = "Mann, diese Shed-Ling sind völlig hohl.", completion = "Danke. Vielleicht kann ein Ho-zen jetzt endlich mal seiner verfiddelten Arbeit nachgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29878] = { id = 29878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bessere Ho-zen-Falle bauen", description = "Eines ist offensichtlich: Die Ho-zen mögen ihre \"Glitschis\".\n\nTief in Eurer meditativen Trance versunken, habt Ihr vereinzelte Bilder und Eindrücke vor Eurem inneren Auge gesehen. Jetzt seid Ihr wieder wach und versucht, Sinn in das Ganze zu bringen.\n\nEin verrückter Plan beginnt in Eurem Kopf, Gestalt anzunehmen. Verrückt genug, um tatsächlich funktionieren zu können...", sourceObjective = "Sammelt 8 Glitschis und 8 heile Tonkrüge aus dem Kittitatasee.", sourceObjectiveStatus = "unverified-source-field" }
quests[29879] = { id = 29879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Ganzen verschlungen", description = "Zurück zu Eurem Dilemma.\n\nIch glaube, Ihr könnt eurem Volk helfen, eine Beziehung zu unseren Ho-zen aufzubauen, so wie es auch unser Volk getan hat.\n\nDer Pfad hinter mir wird Euch zu einem See führen, aus dem die Ho-zen ihre Fische beziehen.\n\nJedes Jahr zu dieser Zeit gibt es in dem See furchterregende Biester, denen viele hungrige Ho-zen zum Opfer fallen.\n\nWenn Ihr einige der Opfer retten und ein paar Fische sammeln könntet, würden die Ho-zen Euch vielleicht freundlicher gesinnt sein.", sourceObjective = "Befreit 5 Ho-zen aus dem Inneren vollgefressener Krokilisken und sammelt 5 Bachsaiblinge am Kittitatasee.", progress = "Nappel hat Glitschis... für mich!?", completion = "Nappel hat Ho-zen gerettet? Und Glitschis gebracht?\n\nHmm, vielleicht Nappel doch nicht so böse.\n\nTuki Tuki hat Djuuk Uukem sowieso noch nie gemocht...", sourceObjectiveStatus = "unverified-source-field" }
quests[29880] = { id = 29880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangen und freilassen!", description = "Ihr legt einen Fisch in jedes Glas und werdet immer optimistischer.\n\nDas könnte funktionieren! Im Idealfall werden die Ho-zen, die Ihr aus Eurer behelfsmäßigen Falle gerettet habt, Euch ein wenig wohlgesinnter sein.\n\nEs wird Zeit, ein paar Köder auszulegen.", sourceObjective = "Verwendet Ho-zen-Fallen im Lager Nooka-Nooka und zerbrecht sie, um 5 gefangene Ho-zen zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[29881] = { id = 29881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die perfekte Farbe", description = "Wie Ihr gesehen habt, gibt es in diesem Hain wunderschöne rosafarbene Blüten. Wenn die Blütenblätter welken, wird der Ton dunkler und verblasst.\n\nWärt Ihr so freundlich, mir einige frisch abgefallene Blütenblätter zu bringen? Nur die, die gerade herabgefallen sind, haben genau die Farbe, die ich brauche.\n\nDaraus kann ich eine atemberaubende Tinte herstellen. Werdet Ihr mir helfen?", sourceObjective = "Sammelt 8 frisch gefallene Blütenblätter.", progress = "Wenn ein Blütenblatt abfällt, bleibt nur wenig Zeit, in der es für den perfekten Farbton verwendet werden kann.", completion = "Ah! Ihr habt ein gutes Auge für Farben. Daraus lässt sich ein hervorragendes Pigment herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29882] = { id = 29882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feder aus Stacheln", description = "Für den perfekten Pinselstrich braucht man auch das richtige Werkzeug. Meine eigenen Pinsel lassen sich nicht mehr reparieren, die Borsten sind so unnachgiebig wie Ho-zen-Haar geworden.\n\nHabt Ihr die Wespen im Arboretum gesehen? Aus ihren Stacheln kann man Schreibfedern herstellen, die sich für jeden Schärfegrad eignen.\n\nKönntet Ihr mir bitte einige besorgen?", sourceObjective = "Sammelt 6 Wespenstachel von Obstgartenwespen.", progress = "Habt Ihr einige Stachel gefunden? Normalerweise würde ich einen Mönch darum bitten, aber die scheinen alle beschäftigt zu sein.", completion = "Vielen Dank. Daraus lassen sich schöne Schreibfedern herstellen. Hier habt Ihr etwas für Eure Mühe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29883] = { id = 29883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Perlflossenproblem", description = "Ich habe nachgedacht.\n\nWir sind hier von aller Versorgung abgeschnitten und weit weg von zu Hause.\n\nZwar scheinen uns diese Perlflossen-Jinyu zu misstrauen, aber sie wirken nicht feindselig.\n\nWenn wir sie davon überzeugen können, dass wir ihre Freunde sind, könnte sich ein Bündnis zwischen unseren Völkern als sehr wertvoll erweisen.\n\n{name}, Ihr müsst mit den Jinyu im Dorf sprechen.\n\nÜberzeugt ihre Anführer, dass sie uns nicht fürchten müssen und dass wir nichts als Frieden wollen.", sourceObjective = "Sprecht mit dem Ältesten Lusshan, Perlenhüter Fujin, Ausbilder Scharffinne und Ot-Temmdo im Dorf der Perlflossen.", completion = "Anscheinend habt Ihr einen guten Eindruck gemacht.\n\nIch bin beeindruckt, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29884] = { id = 29884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Abreise der Spione", description = "Es wird Zeit, dass Sully und ich abreisen. Wir werden unsere Augen nach Hinweisen auf den Weißen Bauern offen halten und uns bald wieder melden.\n\nLeider muss ich Euch die Leitung überlassen, solange sich Admiral Taylor erholt. Lernt so viel Ihr nur könnt von diesen Jinyu, während wir fort sind. Ich erwarte bei unserer Rückkehr einen ausgiebigen Bericht.", sourceObjective = "Schickt die Späher los und sprecht dann mit dem Ältesten Lusshan.", sourceObjectiveStatus = "unverified-source-field" }
quests[29885] = { id = 29885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wegzehrung", description = "Wir haben keine Zeit, um hier zu warten, bis sich der Admiral erholt hat.\n\nSully und ich werden im Norden nach Anduin suchen, aber wir benötigen Vorräte für die Reise.\n\nIm See hier wimmelt es von Tieren, die wir jagen dürfen.\n\nSammelt einige Vorräte, während Sully und ich die letzten Vorbereitungen treffen.", sourceObjective = "Besorgt 6 Schildkrötenflanken.", progress = "Die Zeit ist knapp. Mit jeder Stunde, die wir verlieren, kann der Weiße Bauer weiter weg sein.\n\nWo sind die Vorräte, um die ich gebeten habe?", completion = "Das dürfte genug sein, {name}. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[29886] = { id = 29886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zenheilung", description = "Euer Freund Taylor ist in einem schlechten Zustand. Seine Wunden sind mit Ho-zen-Gift verunreinigt worden, das sehr schwer zu heilen ist.\n\nZum Glück hat mein Volk, das seit vielen Generationen gegen die Ho-zen kämpft, Medizin gegen solche Wunden entwickelt.\n\nDie Blumen, die auf der Oberfläche des Perlsees rings um unser Dorf wachsen, werden für das Gegenmittel benötigt.\n\n{name}, geht schnell und bringt mir ein paar Blüten. Das Leben Eures Admirals steht auf dem Spiel.", sourceObjective = "Sammelt 6 Zenlotus.", sourceObjectiveStatus = "unverified-source-field" }
quests[29887] = { id = 29887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Instrumente des Ältesten", description = "Oje, oje... Der Älteste darf es nicht erfahren!\n\nIch muss bei der Flucht die zeremoniellen Instrumente des Ältesten vergessen haben.\n\nAber... die Mondwasserzuflucht ist jetzt voller Ho-zen!\n\nWas bin ich nur für ein Perlenhüter, dass ich sie einfach zurücklasse?\n\n<Der alte Jinyu vergräbt sein Gesicht in den Händen.>\n\nKönnt Ihr mir wohl helfen?", sourceObjective = "Holt den Stab des Wassersprechers, die zeremoniellen Roben, die Jadekrone und die Rosenholzperlen von den Langfingern der Schlingschwänze zurück.", progress = "Der Älteste ist ein Wassersprecher. Er spricht mit dem Wasser, und es antwortet.", completion = "Ihr habt alles gefunden? Oh, den Geistern des Wassers sei Dank!\n\nIhr habt mir die Schwanzflosse gerettet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29888] = { id = 29888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Lehrensucher aufsuchen", description = "Mir ist aufgefallen, dass Ihr und Eure Leute verzweifelt nach Eurem Prinzen Anduin sucht.\n\nIch kenne jemanden, der Euch vielleicht helfen kann, ein Lehrensucher der Pandaren, der dieses Land besser kennt als jeder andere. Ich weiß nicht, wie er Euch empfangen wird, aber er wird Euch mit ziemlicher Sicherheit genauso neugierig begegnen wie Ihr ihm!\n\nDer Lehrensucher lebt im Wald im Südwesten. Sagt ihm, dass Euch die Perlflossen schicken.", sourceObjective = "Findet Lehrensucher Cho im Pavillon des Träumers im Jadewald.", completion = "Ihr seht Euch bei dem leeren Haus um.\n\nEs scheint, als wäret Ihr am richtigen Ort, doch vom Bewohner ist nichts zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29889] = { id = 29889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geborgtes Gebräu", description = "Der Flasche auf dem Tisch entströmt ein köstlicher Duft.\n\nEin kleiner Schluck kann doch nicht schaden, oder?", sourceObjective = "Kostet das köstliche Gebräu.", completion = "Ich habe gehört, dass solche wie Ihr an unsere Strände gespült worden sind, aber ich hätte nicht erwartet, dass ich einen von Euch direkt vor meiner Haustür finden würde! Was bringt Euch hierher, Fremder?\n\n<Ihr erklärt dem Pandaren Eure Suche nach Prinz Anduin und beschreibt ihm den Jungen.>\n\nSehr interessant! Und die Perlflossen haben Euch zu mir geschickt, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[29890] = { id = 29890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die innere Mitte finden", description = "Das Traumgebräu ist vollendet! Wenn Ihr es dieses Mal trinkt, müsst Ihr die Visionen, die Ihr seht, mit einem inneren Fokus betrachten.\n\nFolgt mir zu meiner Pagode und ich werde Euch lehren, wie Ihr die innere Ruhe erreichen könnt, die uns Pandaren so wichtig ist.\n\nEuer aufgewühltes Gemüt wird Euch viele Ablenkungen präsentieren, doch vergesst nicht, Euch auf Eure innere Mitte zu konzentrieren!", sourceObjective = "Meditiert mit Lehrensucher Cho im Pavillon des Träumers im Jadewald.", completion = "Wie habt Ihr mich gefunden?\n\n<Anduin hört zu, wie Ihr die durch das Traumgebräu hervorgerufene Vision beschreibt.>\n\nDas ist ja erstaunlich! Genau das ist vor einigen Tagen passiert. Seitdem haben wir uns versteckt gehalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29891] = { id = 29891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein starkes Gebräu", description = "Für die Herstellung des Traumgebräus benötigen wir mehrere Zutaten.\n\nUm die Stärke zu verbessern, brauche ich eine Zutat von einer schaurigen Kreatur, dem legendären Nebelschrecken.\n\nAngeblich erscheint diese Kreatur nur dort, wo der Nebel am dichtesten ist.\n\nIm Norden und Osten findet Ihr kleinere Nebelkrabbler in den Sümpfen. Vernichtet diese Kreaturen, bis der Nebelschrecken erscheint, und bringt mir dann sein Herz.", sourceObjective = "Tötet Nebelkrabbler, bis ein Nebelschrecken erscheint, und nehmt ein Nebelschreckenherz an Euch.", progress = "Die Nebel scheinen einen eigenen Willen zu besitzen, was?", completion = "Das ist ein unglaubliches Exemplar! Ich bin überrascht, dass Ihr tatsächlich erfolgreich wart.", sourceObjectiveStatus = "unverified-source-field" }
quests[29892] = { id = 29892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Körper", description = "Der Körper eines Gebräus ist wichtig und bleibt allzu häufig unbeachtet.\n\nUm die perfekte Konsistenz zu erhalten, benötige ich makellose Augen von Sumpfkrokilisken aus dem Osten.\n\nGebt Acht. Diese Kreaturen sind ziemlich grausam.", sourceObjective = "Sammelt 5 makellose Krokiliskenaugen von Sumpfkrokilisken.", progress = "Passt im Sumpf gut auf Euch auf, mein neuer Freund.", completion = "Gibt es da, wo Ihr herkommt, auch Krokilisken?", sourceObjectiveStatus = "unverified-source-field" }
quests[29893] = { id = 29893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Färbung", description = "Das Auffälligste am Traumgebräu ist seine leuchtende traumartige Farbe.\n\nIm Osten könnt Ihr schillernde Bernfliegen finden. Ich benötige ihre Flügel, um die letzte Leuchtfarbe des Gebräus herzustellen.\n\nNehmt dieses Messer und schneidet damit 8 Flügel ab.", sourceObjective = "Sammelt 8 Bernfliegenflügel.", progress = "Habt Ihr die Zutaten besorgt? Es ist fast an der Zeit, das Traumgebräu herzustellen.", completion = "Eine wunderschöne Farbe, seltene Transparenz, schimmernd, aber nicht funkelnd… Sie sind hervorragend.\n\nSo langsam erkenne ich ein großes Potenzial in Euch, Fremdling.", sourceObjectiveStatus = "unverified-source-field" }
quests[29894] = { id = 29894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister des Wassers", description = "Unser Krieg gegen die Ho-zen scheint endlos zu sein, und die Zukunft unseres Stammes ist ungewiss.\n\nDarum hat unser Wassersprecher beschlossen, um die Weisheit des Wassers zu ersuchen.\n\nDer Älteste Lusshan wartet. Bitte bringt ihm die Instrumente, damit sie beginnen können.", sourceObjective = "Sprecht mit dem Ältesten Lusshan und werdet Zeuge der Wassersprechzeremonie.", progress = "<Die Augen des Ältesten verklären sich. Sein Blick wird nach innen gekehrt, in Richtung des Wissens, das er gewonnen hat.>", completion = "Ich habe die Vision gesehen, {name}. Was hat sie Eurer Meinung nach zu bedeuten?\n\nEs ist offensichtlich, dass Ihr eine Rolle darin spielt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29895] = { id = 29895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spur des Weißen Bauern", description = "Der Mantel ist zwar zerschlissen und zerrissen, aber die feine Machart und das königliche Wappen sind unverkennbar.\n\nIhr solltet ihn Eurem Kommandanten der Allianz zeigen.", sourceObjective = "Zeigt Admiral Taylor im Dorf der Perlflossen im Jadewald den Mantel.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[29896] = { id = 29896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stachelschießen", description = "Da wir bereits hier draußen sind, sollten wir nicht mit leeren Händen zurückkehren.\n\nWusstet Ihr, dass die Stachelschweine dieser Gegend das köstlichste, saftigste Steak liefern, das Ihr je gegessen habt?\n\nSie sind wegen ihrer Stachel nicht einfach zu jagen, aber Ihr seht aus, als würdet Ihr damit klarkommen.\n\nBesorgt mir einige Steaks, die ich mit ins Lager nehmen kann.\n\nWir mögen in dieser Wildnis vielleicht rauer werden, aber wir können dennoch essen wie Könige!", sourceObjective = "Besorgt 5 Stachelschweinsteaks.", sourceObjectiveStatus = "unverified-source-field" }
quests[29897] = { id = 29897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mittagessen gibt's nicht umsonst", description = "Die Kämpfe sind vorüber, aber unsere Probleme noch lange nicht.\n\nUnserem Lager gehen langsam die Vorräte aus, und unsere Versorgerin ist nicht aus dem Kampf zurückgekehrt.\n\nEinige behaupten, sie hätten gesehen, wie sie in den Wald im Norden geschleift wurde.\n\nKönnt Ihr bitte nach ihr suchen?", sourceObjective = "Findet Sandra Emerella im Viridianhain im Jadewald.", sourceObjectiveStatus = "unverified-source-field" }
quests[29898] = { id = 29898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heiliges Wasser", description = "Ich bin dankbar dafür, dass Ihr den weiten Weg gemacht habt, um mich zu retten, aber Ren ist schwer verletzt.\n\nDer alte Pandaren hatte keinen Grund, mir zu helfen, und doch hat er für mich sein Leben riskiert.\n\nVor Ausbruch des Fiebers erwähnte er, dass es in der Höhle am Fuße des Hügels heilendes Wasser gäbe.\n\nEs ist gefährlich, aber ich würde alles tun, um meinem Freund zu helfen. Werdet Ihr mir dabei helfen, das Wasser zu holen?", sourceObjective = "Holt heilendes Wasser aus den vier heiligen Schalen in der Höhle der Trauer.", progress = "Vielleicht könnte ich etwas von diesem heilenden Wasser mit nach Sturmwind nehmen.", completion = "Das heilende Wasser müsste Rens Fieber kurzfristig senken, aber das ist keine dauerhafte Lösung.\n\nVielen Dank, {class}. Wir haben ihm wenigstens etwas mehr Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[29899] = { id = 29899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhet in Frieden", description = "Die Geister... die Höhlenbewohner... sie schreien vor Schmerzen... \n\nGefangen... in dieser Welt... können sich nicht... zur nächsten bewegen.\n\nIch... werde verrückt... solange ich… ihre Schreie höre... \n\nBitte… bringt sie... zum Schweigen.", sourceObjective = "Tötet 6 gepeinigte Geister.", completion = "Vielen Dank… Ich bin… froh… da ich weiß… dass die Geister… Frieden gefunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[29900] = { id = 29900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine alte Legende", description = "Mein Vater hat sein Leben dem Studium des Tals der Ewigen Blüten gewidmet.\n\nDas Tal ist ein mystischer Ort, vollkommen abgeschieden nach der Revolution der Pandaren vor 12.000 Jahren. Wir wissen so wenig darüber.\n\nMein Vater ist einigen Hinweisen bis zu der Höhle am Fuße des Hügels gefolgt. Darin befindet sich ein sehr altes Gedicht, das als der Gesang des Tals bekannt ist, aber er kann es nicht an sich nehmen. Es wird von einer Art Geist der Ahnen bewacht.\n\nWenn Ihr ohnehin in diese Richtung wollt, könnt Ihr es ihm dann vielleicht bringen?", sourceObjective = "Holt den Gesang des Tals aus der Höhle der Trauer.", progress = "Habt Ihr… die Schriftrolle gefunden?", completion = "Oh… Das ist das Gedicht! Habt Ihr… es gelesen? Wo liegt… das Tal?", sourceObjectiveStatus = "unverified-source-field" }
quests[29901] = { id = 29901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anduins Entscheidung", description = "Ihr habt für die Freunde des Prinzen getan, was Ihr könnt.\n\nIhr habt Eure Mission erfüllt und den Weißen Bauern gefunden: Prinz Anduin. Admiral Taylor und die anderen SI:7-Agenten werden darauf brennen, den Jungen in Gewahrsam zu nehmen.\n\nEs ist Zeit, nach Hause zurückzukehren.", sourceObjective = "Sagt Anduin, dass es Zeit ist, nach Hause zurückzukehren.", completion = "Er hat WAS gemacht?!?\n\nEr hat Glück, dass ich ihn noch nicht gefunden habe, denn sonst hätte ich ihm den Kopf abgerissen!\n\nWas denkt er sich nur... dieses Tal zu suchen... Das ist kein Verhalten, das eines Prinzen würdig ist!\n\nHätten wir nicht Dringenderes zu erledigen, würde ich unsere gesamte Flotte hinter ihm herschicken!", sourceObjectiveStatus = "unverified-source-field" }
quests[29902] = { id = 29902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf gegen die Flammen", description = "Diese Affen wirken eher wild als intelligent, aber sie sind clever genug zu wissen, dass Feuer eine mächtige Waffe ist.\n\nIch muss wohl nicht erwähnen, dass diese Feuer alles vernichten werden, was wir hier aufgebaut haben, wenn wir uns nicht darum kümmern.\n\nMeine Männer haben bereits alle Hände voll zu tun, daher müsst Ihr Euch darum kümmern. Nehmt diesen Eimer voll Wasser und löscht die Flammen!", sourceObjective = "Löscht 6 Feuer am Hastigen Landgang.", sourceObjectiveStatus = "unverified-source-field" }
quests[29903] = { id = 29903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Passt perfekt", description = "Der Älteste Lusshan und ich sind uns einig, dass wir zusammenarbeiten sollten.\n\nWir werden unser überlegenes militärisches Wissen und unsere Waffen mit den Perlflossen teilen.\n\nDafür haben wir einen mächtigen Verbündeten, falls wir erneut auf die Horde treffen.\n\nNehmt diese Kiste mit Ausrüstungsgegenständen und Waffen. Ihr müsst durch das Dorf gehen und die Jinyu entsprechend ihrer Fähigkeiten mit Waffen ausstatten.", sourceObjective = "Sprecht mit den Aqualythen der Perlflossen und stattet sie mit der richtigen Ausrüstung aus.", completion = "Gut. Jetzt können die Bastarde von der Horde ruhig wieder auftauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29904] = { id = 29904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Größere Fische", description = "Ich habe eine Gruppe aus vielversprechenden Schülern der Perlflossen zusammengestellt, die Kampferfahrung brauchen.\n\nGeht mit ihnen in den Nordosten in die Bambuswildnis und erlegt alle Tiere, auf die Ihr trefft.\n\nKommt erst zurück, wenn sie bereit für den Kampf sind.", sourceObjective = "Bildet die Adepten der Perlflossen aus, indem Ihr 24 Tiere in der Bambuswildnis erlegt.", progress = "Wie machen sich die Schüler?", completion = "Eure Schüler sind vor Kurzem zurückgekehrt. Ich konnte es kaum glauben! Das waren nicht mehr dieselben Jinyu, mit denen Ihr aufgebrochen seid.\n\nHervorragende Arbeit, {class}. Das hätte ich nicht besser machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[29905] = { id = 29905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie brennen", description = "Vorhutsspäher haben gemeldet, dass sich die Ho-zen in den Schlingschwanzgruben mit Verstärkung aus den Stämmen im Norden vereinen.\n\nUnsere Truppen machen sich am Kamm im Nordwesten kampfbereit und warten nur noch auf Euch.\n\nJetzt können wir ihnen zeigen, aus welchem Holz wir geschnitzt sind, und sie endgültig vernichten.", sourceObjective = "Vernichtet 15 Flotsch-Verstärkungstruppen oder Schlingschwanz-Rekruten.", completion = "Das Wasser hatte in Bezug auf Euch recht, {name}. Dank Eurer Bemühungen hat dieses Dorf eine Zukunft. Wir werden nie vergessen, was Ihr uns gelehrt habt, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29906] = { id = 29906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carpe Diem", description = "Auch wenn die Ho-zen unkoordiniert erscheinen, steckt eine Ordnung hinter dem Chaos. Ihr Anführer, Häuptling Gukgut, ist der gerissene Lenker ihrer Angriffe.\n\nEr organisiert sie bei der großen Grube im Ho-zen-Lager im Nordwesten.\n\nSchlagt jetzt zu und zeigt keine Gnade, {name}, denn das würde er auch nicht tun.", sourceObjective = "Vernichtet Häuptling Gukgut.", completion = "Ohne ihren Anführer wird bei den Ho-zen erneut das Chaos ausbrechen.\n\nHeute genießen wir unseren Sieg! {name}, Ihr kamt als ein Fremder zu uns, doch Ihr verlasst uns als Freund.\n\nVon jetzt an seid Ihr hier außerordentlich geschätzt - als Freund und Verteidiger des Perlflossenstammes.", sourceObjectiveStatus = "unverified-source-field" }
quests[29907] = { id = 29907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chen und Li Li", description = "Meine Nichte und ich sind neu hier in Pandaria. Genau wie Ihr vermutlich. Wir kommen von der Wandernden Insel und sind nur zu Besuch hier. Eigentlich wissen wir gar nicht, wohin wir gehen wollen.\n\nAuf dem Hof dort könnten wir uns doch ausruhen und etwas trinken. Was meinst du, Li Li?\n\nMöchtet Ihr uns nicht vielleicht ein Stück des Weges begleiten, {race}?", sourceObjective = "Folgt Chen Sturmbräu zu Pangs Hof.", completion = "Herzlich willkommen, liebe Besucher! Möchtet Ihr die Rüben meines Sohnes probieren? Oder vielleicht ein paar Schweine kaufen?\n\nBitte fühlt Euch ganz wie zu Hause. Ich habe hier jede Menge Platz.", sourceObjectiveStatus = "unverified-source-field" }
quests[29908] = { id = 29908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schier unendliches Ärgernis", description = "Ich muss mich für den Zustand hier entschuldigen. Die Shed-Ling, diese kaninchenartigen Kreaturen vom Fuße der Berge, sind immer weiter auf den Hof meiner Familie vorgedrungen und haben unsere Erntepflanzen, die übrigens normalerweise viel größer und viel leckerer sind, geschädigt.\n\nIch bin kein Soldat... Aber Ihr seht aus wie einer! Könntet Ihr nicht ein paar dieser Shed-Ling von unserem Land vertreiben?", sourceObjective = "Tötet 8 Raffzahn-Shed-Ling, Werkzeugdiebe oder Unruhestifter. Tötet dann 18 Raffzahnnervensägen.", completion = "<Pang untersucht die nähere Umgebung seines Hofes.>\n\nTja, sie sind zwar nicht ALLE weg, aber zumindest sind es jetzt weniger. Und sie halten auch ihre Ohren nicht mehr ganz so hoch.\n\nIch glaube, sie haben Angst vor Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29909] = { id = 29909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geringe Rübenausbeute", description = "Ich weiß Eure Hilfe wirklich sehr zu schätzen, {name}. Und ich hätte noch eine weitere Aufgabe für Euch.\n\nMein Sohn, Ang, betreibt einen kleinen Hof am Fuße dieses Hügels. Er hätte mir heute morgen ein paar Früchte und etwas Gemüse bringen sollen, aber er ist bis jetzt noch nicht aufgetaucht.\n\nWürdet Ihr vielleicht dort runtergehen und mal nachsehen, was da los ist?", sourceObjective = "Findet Ang Donnerfuß.", completion = "Was? Wer seid...? Mein Vater hat Euch geschickt?\n\nPah... Er kann ja manchmal so neugierig sein. Ich habe hier alles unter Kontrolle.", sourceObjectiveStatus = "unverified-source-field" }
quests[29910] = { id = 29910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miese Murmler", description = "Ich bin heute morgen losgegangen, um meinem Vater beim Kampf gegen die Shed-Ling zuzusehen. Und als ich zurückkam, war der Hof voller Murmeltiere!\n\nIch will sie gar nicht töten, aber wir müssen sie trotzdem loswerden. Hey, ich hab' eine Idee! Wir könnten doch ihre Baue verschließen!\n\nStopft etwas Dreck in die Löcher, damit sie nicht mehr auf dem Gelände unseres Hofes rauskommen.", sourceObjective = "Vertreibt 6 mollige Murmeltiere vom Donnerfußhof und verschließt 6 Murmeltierbaue.", progress = "Die Murmeltiere werden sich nicht darüber freuen, dass Ihr ihre Baue verschließt.", completion = "Ich danke Euch, guter Mann! Jetzt kann ich mich wieder meinen Pflichten widmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29911] = { id = 29911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Praktisch perfekte Produkte", description = "Bitte, {name}. Das wird meinem Vater gefallen.\n\nDanke nochmals für Eure Hilfe mit den Shed-Ling.", sourceObjective = "Bringt die Kiste mit frischem Obst und Gemüse zu Pang Donnerfuß.", progress = "Rieche ich da etwa Rüben?", completion = "Ho ho! Na, so etwas sehe ich gerne!", sourceObjectiveStatus = "unverified-source-field" }
quests[29912] = { id = 29912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fantastisches Fräulein Fanny", description = "Der Großteil dieses Gemüses wird zwar verkauft, aber etwas davon möchte ich für meine Familie behalten. Insbesondere mein Neffe Liang braucht etwas zum Füttern seiner Schweine.\n\nLeider wimmelt es auf dem Weg zu Liangs Hof nur so von Raffzahn-Shed-Ling. Wir müssen Fräulein Fanny um Hilfe bitten.\n\nBringt etwas von dem Essen, das wir gesammelt haben, zu Fräulein Fanny, die neben meinem Haus steht. Bittet sie dann - NETT! - darum, es zu Liangs Hof zu befördern.", sourceObjective = "Bringt Angs riesige rosa Rübe, Angs Sommerwassermelone und Pangs besonders scharfen Tofu zu Fräulein Fanny, und bittet sie darum, sie zu befördern. Das Essen muss zum Gehöft Donnerfuß gebracht werden.", completion = "Wie ich sehe, habt Ihr das Essen vom Hof meines Onkels hierher geschickt. Vielen Dank.\n\nMeine Schweine sind wählerisch, aber diese Rüben und Melonen gehören zu ihrem Lieblingsessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29913] = { id = 29913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleisch um jeden Preis", description = "Wie ich bereits sagte, sind meine Schweine sehr wählerisch. Sie brauchen Fleisch, um stark zu werden, aber sie mögen kein Hammelfleisch und kein Yak-Fleisch - und Schweinefleisch will ich ihnen schon gar nicht vorsetzen.\n\nSie fressen allerdings Mushan-Fleisch und mögen Schildkröten. Beides findet Ihr in großer Zahl im Westen.\n\nMeine Jagdfähigkeiten sind zugegebenermaßen ziemlich dürftig. Könnt Ihr einem jungen Bauern und seinen Schweinen helfen?", sourceObjective = "Besorgt 4 Mushanschulterstücke und 80 Fetzen Schildkrötenfleisch.", progress = "Es tut mir weh, sie vor Hunger quieken zu hören.\n\nWenn man eine Zeit lang Schweinebauer ist, erkennt man den Unterschied zu normalem Quieken.", completion = "<Liang sieht sich das Fleisch an.>\n\nIhr seid nicht nur ein {class}, sondern wohl auch ein Metzger, oder? Ihr habt ein Auge für hochwertige Schweinenahrung, Nachbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[29914] = { id = 29914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in den Stall", description = "Ich versuche stets, meine Tiere im Auge zu behalten, aber ab und zu büchst doch eins aus. Bei dem ganzen Chaos, das die Shed-Ling verursachen, wurde ich wohl für einen Moment etwas unachtsam und einige meiner Schweine konnten entkommen.\n\nWürdet Ihr sie für mich suchen? Ich würde als Erstes den Hügel runter Richtung Westen gehen.", sourceObjective = "Sucht Jian, Ling und Stinki.", progress = "Habt Ihr sie gefunden? Ich glaube, es fehlen drei.", completion = "Da sind sie ja! Los, zurück in den Schweinestall ihr drei!\n\n<Liang sieht zu Euch hoch.>\n\nVielen Dank, Nachbar. Ich weiß Eure Hilfe wirklich zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29915] = { id = 29915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachbarschaftliche Pflichten", description = "Ich bin wohl nicht der Einzige, der Probleme mit seinen Tieren hat. Eins von Francis' Schafen ist diese Woche schon zum dritten Mal zu mir auf den Hof gekommen. Vielleicht braucht er Hilfe beim Hüten seiner Herde?\n\nIhr solltet ihm einen Besuch abstatten, <Nachbar/Nachbarin>. Und nehmt bitte dieses arme Ding mit.", sourceObjective = "Bringt das entlaufene Lamm zu Francis dem Hirtenjungen.", progress = "Oh... Ihr habt eines meiner... meiner Lämmer?", completion = "Ihr hättet das Lamm wirklich nicht zu mir zurückbringen sollen. Es... Es war im Schweinestall sicherer aufgehoben als hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[29916] = { id = 29916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneidende Krallen und geifernde Schnäbel", description = "Zuerst kamen die Falken. Ihr habt bestimmt welche am Himmel kreisen sehen.\n\nKurz darauf folgten dann die Wölfe. Ich schätze, sie haben gerochen, dass ich schwach bin.\n\nIch bin nicht im Ansatz so tapfer, wie Meister Shang es dachte. Der Meister wird sich sehr über mich ärgern, wenn ich nichts gegen diese Bedrohungen unternehme.\n\nKönnt... könnt Ihr mir vielleicht helfen, <mein Herr/meine Dame>?", sourceObjective = "Tötet 5 diebische Ebenenfalken und 6 diebische Wölfe.", completion = "Sie... sie haben nicht aufgehört, aber zumindest haben wir uns zur Wehr gesetzt. Stimmt's?", sourceObjectiveStatus = "unverified-source-field" }
quests[29917] = { id = 29917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lupello", description = "Ich habe nachgedacht... Die Wölfe hören mit ihren Angriffen vielleicht auf, wenn wir ihren Leitwolf töten.\n\nWir nennen ihn Lupello, und er streift am gegenüberliegenden Ufer entlang.\n\n<Francis' Aufmerksamkeit wird von einem weiteren Angriff in Beschlag genommen. Vielleicht solltet Ihr Euch selbst um Lupello kümmern.>", sourceObjective = "Tötet Lupello.", progress = "Was wohl Meister Shang sagen wird, wenn er davon erfährt?", completion = "Ich weiß, dass eigentlich ich gegen sie kämpfen sollte. Ich scheine wohl einfach nicht zum Hüten von Schafen geboren zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[29918] = { id = 29918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Sachen Tapferkeit", description = "<Meister Shang spricht mit seinem Hirtenjungen.>\n\nFrancis, du musst Tapferkeit zeigen! Du hast alles, was man braucht, um ein guter Hirte zu sein - du musst dich nur deinen Ängsten stellen!\n\n<Er sieht zu Euch rüber.>\n\nHeh, Ihr! Ihr habt doch schon dem Rest meiner Familie geholfen. Francis ist wie ein zweiter Sohn für mich.\n\nZeigt meinem Schüler, was Furchtlosigkeit bedeutet. Besiegt mit diesem Seil einen der großen weißen Falken über uns.\n\n<Shang zeigt zum Himmel, blickt zu Francis und geht.>", sourceObjective = "Verwendet das Viehhüterlasso, um einen großen weißen Ebenenfalken einzufangen und zu töten.", progress = "Ihr seid furchtlos. Das kann ich in Eurem Herzen spüren.", completion = "Francis braucht länger, als ich gedacht habe, um ein guter Hirte zu werden. Wir alle durchlaufen solche Phasen... Auch mein Sohn Liang war einmal schwach. Genauso wie ich.\n\nAber er wird es lernen. Das ist der Weg der Donnerfußens.", sourceObjectiveStatus = "unverified-source-field" }
quests[29919] = { id = 29919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Dumme, ein Getränk", description = "Oh, hallo, {name}. Das ist jetzt schon das vierte Mal, dass wir uns begegnen, oder?\n\nNun... mein Fässchen wird ziemlich schnell immer leerer. Ich habe von einer Brauerei im Südwesten gehört. Wir sind auf dem Weg dorthin. Wollt Ihr uns begleiten?", sourceObjective = "Begleitet Chen Sturmbräu und Li Li zur Brauerei im Südwesten.", completion = "Wenn Ihr Bier sucht, seid Ihr hier genau richtig, Nachbar.\n\nHm, ähm... entschuldigt das Durcheinander. Hatte in den letzten Tagen ein Problem mit Shed-Ling.", sourceObjectiveStatus = "unverified-source-field" }
quests[29920] = { id = 29920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erlaubnis erhalten", description = "Mein Schatz Lo hat um die Erlaubnis der Pandriarchen ersucht, mich heiraten zu dürfen. Obwohl sie sich in anderen Sphären befinden, würde ihre Zustimmung uns viel bedeuten.\n\nDa sie jedoch Geister sind, konnten sie weder unsere Geschenke noch unsere Tribute beeindrucken. Um ihre Gunst zu gewinnen, verlangen sie, dass entweder Lo oder ein Champion einen der ihren im Kampf besiegt.\n\nLo ist ein guter Mann, aber kein Kämpfer.\n\nWollt Ihr unser Champion sein?", sourceObjective = "Fordert Pandriarch Zapfgold, Pandriarch Windpelz und Pandriarch Dornstab heraus und besiegt sie.", progress = "Die Pandriarchen haben sich ihren Ruf im Leben erworben und danach beibehalten. Ich weiß beim besten Willen nicht, wie Ihr sie besiegen wollt.", completion = "Sie… Sie haben zugestimmt?! Großartig! Vielen Dank! Dank ihres Segens werden wir die glücklichsten Pandaren des ganzen Landes sein!\n\nBitte nehmt das. Es sollte eigentlich ein Tribut an die Pandriarchen sein, aber sie waren nicht interessiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[29922] = { id = 29922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Weisheit", description = "Lehrensucher Cho hat während Eurer Abwesenheit nach Euch gefragt.\n\nEr braucht dringend Eure Hilfe im Ort Morgenblüte im Norden. Den Grund dafür hat er nicht genannt.\n\nSprecht mit Drachenmeister Ut-Nam. Er wird Euch mit Freuden dorthinschicken.", sourceObjective = "Sprecht mit Drachenmeister Ut-Nam, um nach Morgenblüte zu gelangen.", progress = "Ah! Ihr habt es geschafft. Fantastisch.", completion = "Eure Taten haben eine längst vergessene Erinnerung an eine uralte Prophezeiung hervorgerufen. Das muss untersucht werden.\n\nFür die Untersuchung benötige ich allerdings Jade. Ich habe Toya gebeten, so viel zu sammeln, wie er kann, und sie Euch zu geben, sobald er fertig ist. Bringt sie mir und wir werden versuchen, das uralte \"Omen des Kaisers\" zu entschlüsseln.\n\nWährend er Jade sammelt, könnt Ihr Euch hier gerne umsehen. Ihr werdet sehen, die Leute in diesem Ort können jemanden wie Euch gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29923] = { id = 29923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Traumgebräu", description = "Das Traumgebräu ist fertig.\n\nTrinkt es am Stein des Sehers rechts der roten Pagode.\n\nSuchet und findet.", sourceObjective = "Trinkt das Traumgebräu am Stein des Sehers und findet den Weißen Bauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29924] = { id = 29924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet Kher Shan", description = "Kher Shan ist ein gemeiner Knatzel.\n\nHat alle meine Söhne abgeflotscht! Ick Ick, Nag Nag, Friss Frass, Beissi Beissi und die anderen, die mir nicht mehr einfallen.\n\nNappel will Ho-zen helfen? Abflotschen Kher Shan!\n\nDer Knatzel ist da drüben.\n\n<Nibi Nibi zeigt nach Osten.>", sourceObjective = "Tötet Kher Shan im Tigergehölz.", sourceObjectiveStatus = "unverified-source-field" }
quests[29925] = { id = 29925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wir entbehren können", description = "Ich habe jeden nur möglichen Gefallen eingefordert. Das ist alles, was wir haben.\n\nCho muss Großes vorhaben!\n\nSagt mir Bescheid, wenn Ihr bereit seid, ihn aufzusuchen – ich habe ein Transportmittel für Euch vorbereitet.", sourceObjective = "Bringt die geplünderte Jade zu Lehrensucher Cho beim Omen des Kaisers. Bittet Toya in Morgenblüte um ein Transportmittel.", progress = "Seid gegrüßt, {name}! Dann habt Ihr meine Nachricht also erhalten?", completion = "Ich wusste, dass Toya das für mich erledigen würde!\n\nEr kann alles besorgen, wisst Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[29926] = { id = 29926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unglücksjade", description = "Habt Ihr je eine Schieferspinne gesehen, {class}? Normalerweise sind sie harmlos und fressen Steine, aber neuerdings haben sie Geschmack an Jade gefunden. Einige nennen sie schon \"Knabberer\".\n\nVor einigen Tagen sind wir auf ein großes Nest dieser Viecher gestoßen. Sie verbreiteten sich in den Tunneln und drehten durch. Sie haben alles in Sichtweite aufgefressen – auch einige unserer Leute.\n\nGeht da rein und vernichtet sie, damit uns noch Jade bleibt. Der Steinbruch liegt direkt westlich von hier.", sourceObjective = "Erschlagt 12 Grünsteinknabberer und 6 Grünsteinverschlinger im Grünsteinbruch.", completion = "Unfassbar... Ihr habt es wirklich geschafft!\n\nSeid Ihr auf der Suche nach einer Festanstellung, Bruder? Jemanden wie Euch könnte ich hier gut gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29927] = { id = 29927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manns Mann", description = "<Auf einmal senkt die Vorarbeiterin ihre Stimme.>\n\nHört mal, das ist nicht leicht... Ich muss Euch um einen weiteren Gefallen bitten. Mein törichter Ehemann Hao ist Schichtleiter im Steinbruch. Ich habe ihm gesagt, es sei zu gefährlich und er soll nicht zurückgehen, aber er ist so dickköpfig wie ein Ho-zen und doppelt so dumm. Angeblich wird er zur \"moralischen Unterstützung\" gebraucht.\n\n<Mann schnaubt.>\n\nWas ist denn mit meiner moralischen Unterstützung? Was soll ich denn machen, wenn der Idiot stirbt?!\n\nBitte... Haltet nach ihm Ausschau, und sagt ihm, er soll nach Hause kommen.\n\n<Ihr Blick wird sanft, bevor sie sich abwendet.>", sourceObjective = "Sucht Hao Mann im Grünsteinbruch.", completion = "<Hao sieht Euch an und versucht, sich aus dem Geröll zu befreien.>\n\nNein, nein. Ich hab's gleich. HNNGHHH!!\n\nGut, vielleicht auch nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29928] = { id = 29928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich hab keine Jade und muss schreien", description = "Unsere ganze Jadeversorgungslinie ist auseinandergebrochen. Die Minen sind Todesfallen, die Moral ist auf dem Tiefpunkt, und als ob das noch nicht schlimm genug wäre, wimmelt es im Steinmetzviertel jetzt von Wassergeistern!\n\nSelbst die Pflanzen wollen mich ruinieren!\n\nWenn Ihr die Jade so dringend benötigt, dann folgt der Straße in Richtung Südwesten bis zum Steinmetzviertel und holt sie Euch selbst von diesen besseren Essstäbchen.", sourceObjective = "Holt 15 Jadebrocken von den schelmischen Waldgeistern im Steinmetzviertel von Grünstein.", progress = "<Mann sieht Euch mit großen Augen und geblähten Nasenflügeln an.>", completion = "Fangen? Sie haben damit FANGEN gespielt?!\n\nIch hoffe, Ihr habt diesen herumlaufenden Zahnstochern gezeigt, was Ihr davon haltet.\n\nVielleicht seid Ihr ja doch nicht so übel. Ich brauche jemanden, der mir bei meinem Problem im Steinbruch helfen kann.\n\nUnd wenn ich mir ansehe, was die Lehrensucher hier vorhaben, denke ich, dass Ihr noch sehr viel mehr Jade brauchen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29929] = { id = 29929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Falle!", description = "<Hao drückt mit aller Kraft gegen das Geröll.>\n\nHNNNGHHH!!\n\nLasst mich raten: Meine Frau schickt Euch? Man stelle sich das vor, meine zarte Schneelilie macht sich Sorgen. Ha ha! Sie ist immerzu besorgt um mich. Hört mal – HNNGHH!!! – es braucht schon mehr als einen kleinen – HNNGGHHH!! – Einsturz, um den alten Hao kleinzukriegen.\n\nAber einige meiner Leute stecken in Schwierigkeiten. Helft ihnen, wenn Ihr sie findet, ja? Ich komme schon klar.\n\nWirklich.", sourceObjective = "Befreit 8 Grünsteinbergarbeiter im Grünsteinbruch.", completion = "<Hao lacht fröhlich.>\n\nIch habe gesehen, wie sie rausgelaufen sind, als wäre der alte Kher Shan selbst hinter ihnen her.", sourceObjectiveStatus = "unverified-source-field" }
quests[29930] = { id = 29930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was mein ist, ist Euer", description = "So, Ihr braucht also Jade, was? Ich würde mal sagen, dass wir Euch wenigstens das schulden - wir haben genug davon im Steinbruch, und dank Eurer Hilfe sind wir bald wieder im Zeitplan.\n\nIch sollte vermutlich zu meiner Frau zurück, dann kann ich Euch und diesen Wagen voller schöner Sachen auch gleich mit zu ihr nehmen.\n\nBis jetzt ist mir noch <kein/keine:r> {race} untergekommen, <den/die:r> ich nicht mit meinem Wagen bugsieren konnte. Klettert hinten drauf und lasst den guten alten Hao nur machen.", sourceObjective = "Steigt in den Jadewagen und fahrt mit Hao zurück zum Omen des Kaisers.", progress = "Also? Wo ist Hao?\n\nSagt mir nicht, Ihr konntet ihn nicht finden...", completion = "Ihr habt es geschafft! Ihr bringt mir meinen Honigbären zurück!\n\nOh, vielen Dank, {name}! Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[29931] = { id = 29931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schlangenherz", description = "Ihr habt hier gute Arbeit geleistet, <Kleiner/Kleine>. Dank Euch haben wir eine ganze Menge zusätzliche Jade und ich wüsste da jemanden, der sie gut gebrauchen könnte.\n\nMein Freund, Vorarbeiter Raike, leitet das große Statuenprojekt am Schlangenherz.\n\nBringt ihm eine Ladung Jade und sagt ihm, seine alte Freundin Mann lässt grüßen. Er wird eure Ankunft sehnlich erwarten.", sourceObjective = "Sprecht mit Vorarbeiter Raike am Schlangenherz im Jadewald.", completion = "Sehe ich das richtig? Eine komplette Lieferung reiner, hochwertiger Jade?\n\nSo ein Glück. Ich wusste, dass uns Vorarbeiterin Mann nicht im Stich lassen würde.\n\nOh, und Ihr natürlich auch nicht. Danke fürs Bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29932] = { id = 29932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tempel der Jadeschlange", description = "Ihr habt uns hier einen enormen Dienst erwiesen, <Reisender/Reisende>\n\nDa wir nun genügend Jade für die Fertigstellung der Statue haben, sollten wir Yu'lon der Jadeschlange von unseren Fortschritten berichten.\n\nSprecht bei Eurer Ankunft mit der Ältestenweisen Wind-Yi am Eingang zum Tempel der Jadeschlange.\n\nWenn Ihr Eure Reise beschleunigen wollt, sprecht mit Drachenmeister Shoku. Ich bin mir sicher, dass er einen Drachen für Euch entbehren kann.", sourceObjective = "Sprecht mit der Ältestenweisen Wind-Yi vor dem Eingang zum Tempel der Jadeschlange. Sprecht mit dem Drachenmeister Shoku für einen Ritt zum Tempel.", completion = "Ihr bringt Kunde vom Schlangenherz?\n\n<Der Ältestenweise hört sich geduldig an, was in den Jademinen geschehen ist.>\n\nDanke, dass Ihr den ganzen Weg hierher gekommen seid, Fremder. Doch ich kann im Moment nicht zulassen, dass Ihr mit der Jadeschlange sprecht.\n\nDie Uralte ist sehr beschäftigt und, wie Ihr sehen könnt, momentan auch nicht anwesend.", sourceObjectiveStatus = "unverified-source-field" }
quests[29933] = { id = 29933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine Beine!", description = "Du wirklich Freund der Ho-zen, Nappel? Schauen wir doch mal...\n\nDie Ho-zen aufm Flotschhügel haben keine Köder für Glitschis mehr. Beine von Tigerfliegen am besten, die zucken schön im Wasser!\n\nBo Bo keine Lust auf Stiche. Nappel besorgt Köder und bringt aufn Hügel.", sourceObjective = "Sammelt 30 Käferbeine von Tigerfliegen im Tigergehölz.", progress = "Glitschiessen!", completion = "Ha! Ha! Nappel ist der Oberknatzel!", sourceObjectiveStatus = "unverified-source-field" }
quests[29934] = { id = 29934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Rabenholdt", description = "Wenn das Ei wirklich im Rabenholdtanwesen ist, dann können wir keinen Frontalangriff riskieren. Es könnte zerstört werden. Jemand muss sich hineinschleichen und die Wahrheit herausfinden.\n\nDas seid Ihr, {name}.\n\nMostrasz wird Euch bei der Infiltrierung des Anwesens helfen. Sprecht draußen mit ihm, dann fliegt gemeinsam nach Rabenholdt. Viel Glück!", sourceObjective = "Sprecht mit Mostrasz am Zinnoberrefugium und fliegt mit ihm zum Rabenholdtanwesen.", completion = "So weit so gut. Wollt Ihr dann ein wenig spionieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[29935] = { id = 29935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehl ist Befehl", description = "Hmm, vielleicht Nappel doch nicht so böse!\n\nAndere Kahlhäute nicht nett zu Ho-zen.\n\nHo-zen haben dies von bösen Nappel gestohlen!\n\nAlle Nappelbeute geht an Kah Kah - auf Befehl des Häuptlings!\n\nHier, Nappel. Nimm es. Kah Kah will bestimmt neuen Freund der Ho-zen kennenlernen.\n\nSein Lager ist im Süden vom Flotschhügel.", sourceObjective = "Bringt die Allianzbefehle zu Häuptling Kah Kah auf dem Flotschhügel.\n\nBereitgestellter Gegenstand:", completion = "Hmm.\n\nNette Nappel kämpfen gegen gemeine Nappel?\n\nHo-zen werden auch gegen gemeine Nappel kämpfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29936] = { id = 29936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sofortmitteilung", description = "Willkommen, Nappel! Ich Kah Kah - Häuptling von Ho-zen aufm Flotschhügel.\n\nDjuuk Uuken wollte Häuptling sein, aber guter Nappel hat ihn gut geflotscht - großes Geschenk für Kah Kah.\n\nHo-zen hat auch Geschenk für guten Nappel. Geschenk kommt von großem Absturz. Ho-zen haben für Nappel drauf aufgepasst.", sourceObjective = "Nutzt das Signalleuchtfeuer der Höllschreis Faust nahe Häuptling Kah Kah auf dem Flotschhügel.", completion = "Beeindruckend, {name}.\n\nEs wäre mir nie in den Sinn gekommen, dass wir uns irgendwie mit diesen Kreaturen anfreunden können.\n\nNun können wir uns auf wichtigere Dinge konzentrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[29937] = { id = 29937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorniges Geflügel", description = "Sie mögen gern Fisch, was? Wie wäre es, wenn wir beenden, was Ihr begonnen habt, und sie dazu bringen, uns zu LIEBEN?\n\nIch habe noch immer etwas Schwarzpulver aus dem Wrack, aber ich brauche etwas um die Fische anzulocken.\n\nInnereien wären gut – das hat noch immer geklappt. Südlich der Stadt habe ich einige Vögel am Himmel gesehen.\n\nUnd? Worauf wartet Ihr noch?", sourceObjective = "Sammelt 6 Handvoll Vogeleingeweide von Blutkrallen in den Knatzelgründen.", progress = "Ihr habt das Zeug doch nicht mit den Händen angefasst, oder?", completion = "Ja!\n\nDas ist genau das, was ich haben wollte. Wartet es nur ab...", sourceObjectiveStatus = "unverified-source-field" }
quests[29938] = { id = 29938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde und Feinde", description = "Verfiddelte Jinyu flotschen Kah Kahs Neffen!\n\nNappel hat viele Ho-zen abgemurkst. Jetzt muss Nappel viele Jinyu murksen.", sourceObjective = "Tötet 7 Strandläufer der Jinyu am Glitschifluss.", sourceObjectiveStatus = "unverified-source-field" }
quests[29939] = { id = 29939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichtes Ziel", description = "So. Ich habe die Vogeleingeweide über dem Sprengstoff platziert.\n\nIch nenne sie Filetierbomben und habe ein Patent darauf angemeldet.\n\nDa Ihr Euch mit diesen Kerlen angefreundet habt, sollte ich Euch vielleicht die Ehre überlassen?\n\nZündet einfach die Zündschnur an und lasst sie an der Düsterbank hochgehen!", sourceObjective = "Benutzt die Filetierbomben an der Düsterbank und sammelt 5 explodierte Glitschis.", progress = "Mir ist noch keine Krise untergekommen, die sich nicht mit Dynamit lösen ließ.", completion = "Wir haben gerade die Nahrungsbeschaffung dieser Kretins… äh, Ho-zen revolutioniert.\n\nSie werden nie wieder die Alten sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[29940] = { id = 29940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geklautes Gemüse", description = "Gut, ich gebe es zu. Nein, ich habe hier NICHT alles unter Kontrolle. Ich musste mich den ganzen Morgen mit Shed-Ling herumschlagen. Ich konnte sie zwar von meinem Anwesen vertreiben, aber sie haben etwas von meiner Ernte mitgenommen.\n\nSie haben die Sachen zum Fluss runter Richtung Süden gebracht. Ich habe keine Ahnung, was sie damit tun, wahrscheinlich jedoch nicht essen.\n\nWenn mein Vater jetzt seine Lieferung will, brauche ich Hilfe, um meine gestohlene Ernte zurückzuholen. Könnt Ihr mir dabei helfen?", sourceObjective = "Besorgt 5 gestohlene Rüben und 5 gestohlene Wassermelonen.", progress = "Wenn mein Vater sein Gemüse will, brauche ich Eure Hilfe.", completion = "Perfekt.\n\n<Ang sieht sich die zerschrammten Rüben und die matschigen Wassermelonen an.>\n\nWas haben die denn bloß damit ANGESTELLT!?", sourceObjectiveStatus = "unverified-source-field" }
quests[29941] = { id = 29941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jenseits des Horizonts", description = "Ich erkenne, was Ihr hier geleistet habt, {class}. Mein Bericht an den Kriegshäuptling wird auch Eure Taten auflisten.\n\nAber wir haben keine Zeit zum Ausruhen!\n\nDieses Land muss kartografiert und auf die Besiedlung durch die Horde vorbereitet werden. Ich habe bereits eine Mannschaft dafür zusammengestellt.\n\nFindet sie, bevor sie es sich hier bequem machen. Teilt ihnen mit, was sie zu tun haben, und versucht, Eure neuen Freunde davon zu überzeugen, ihnen einen Führer an die Seite zu stellen.\n\nIhr werdet hier bei mir bleiben. Wir haben Vorbereitungen zu treffen.", sourceObjective = "Sprecht mit Shokia, Unteroffizier Gorrok, Schattenmeisterin Kiryn und Häuptling Kah Kah.", progress = "Ist das Außenteam unterwegs, {name}?", completion = "Gute Arbeit, {name}.\n\nDas Außenteam, das Ihr zusammengestellt habt, ist aufgebrochen.\n\nHoffentlich war Gorrok schlau genug, das zerfetzte rote Hemd auszuziehen. Ich bewundere seinen Patriotismus, aber er hat es seit dem Verlassen von Orgrimmar getragen.\n\nWenn er es trägt, werden sie niemanden überraschen können...", sourceObjectiveStatus = "unverified-source-field" }
quests[29942] = { id = 29942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dummer Nappel, Glitschis sind für Ho-zen", description = "Denkst du, Ho-zen sind verrückt, Nappel? Warte, bis du Ho-zen ohne Glitschis siehst!\n\nNicht genug Glitschis für Ho-zen und Nappel.\n\nSchnapper! Ho-zen hassen verfiddelte Schnapper. Nappel können alle Schnapper essen.\n\n<Kritsche Kratsche deutet gen Süden.>", sourceObjective = "Besorgt 4 Schnappersteaks an der Düsterbank.", progress = "Nappel alle verfiddelte Schnapper geflotscht?", completion = "Jetzt haben alle Futter. Kritsche Kratsche besitzt viel Weisheit der Ho-zen.\n\nVielleicht Kritsche Kratsche eines Tages Häuptling sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[29943] = { id = 29943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guerillas in unserer Mitte", description = "Prinz Anduin Wrynn. Der Sohn des Königs unserer Feinde! Das Glück ist der Horde erneut gewogen, {name}.\n\nAber es gibt eine Kehrseite der Medaille: Wir waren naiv zu glauben, das Kind wäre allein.\n\nJeder Allianzabschaum in diesem Land wird jetzt verzweifelt nach diesem kostbaren Prinzen suchen.\n\nGemeinsam werden wir das Gebiet durchkämmen und seine Möchtegernretter ausschalten.", sourceObjective = "Vernichtet 8 Allianzinfiltratoren in der Nähe des Idyllischen Aussichtspunktes.", completion = "Ja!\n\nBei Thralls blutiger Faust, die Jagd auf die Allianz hat mir gefehlt!", sourceObjectiveStatus = "unverified-source-field" }
quests[29944] = { id = 29944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alphatiere", description = "Bevor ein Fass aufgemacht wird, gibt es noch Arbeit. Diese Shed-Ling sind kein bisschen anders als die Shed-Ling auf der Wandernden Insel... Eine Plage, die sich so schnell vermehrt wie die Kaninchen, denen sie ähnelt.\n\nNatürlich könnten wir jeden einzelnen Shed-Ling töten, aber wozu unnötiges Blutvergießen? Schalten wir einfach ihre Alphatiere aus, damit sie sich nicht mehr so schnell... fortpflanzen.", sourceObjective = "Tötet Aiyu die Bratpfanne, Jinanya die Klauenklinge und Hoppelkoller.", progress = "Diese Shed-Ling haben seltsame Sitten und noch seltsamere Namen.", completion = "<Chen nickt.>\n\nGut gemacht, {name}. Ihr kämpft nicht schlecht.\n\nWas meint Ihr – schließen wir uns für das zusammen, was als Nächstes kommt?", sourceObjectiveStatus = "unverified-source-field" }
quests[29945] = { id = 29945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus gelb und rot wird orange", description = "Onkel Chen sagt, wir werden diesem Kerl mit seinem Shed-Ling-Problem helfen. Kein Problem! Ich LIEBE es, Shed-Ling zu ärgern.\n\nDas ist der Plan: Wir malen ein paar Rüben orange an, und dann lassen wir die Shed-Ling glauben, es seien Karotten.\n\nDas wird ein Riesenspaß.\n\nIch werde Rüben besorgen. Sucht Ihr in der Zwischenzeit etwas zum Herstellen von essbarer Farbe.", sourceObjective = "Besorgt 10 Wiesenringelblumen und 40 mit Tierblut gefüllte Phiolen.", progress = "Habt Ihr das Zeug, um die Farbe herzustellen? Ich habe in der Zwischenzeit ein paar Rüben eingesammelt.", completion = "Hey, hey, HEY! Ihr habt BLUT mitgebracht? Ich schätze, ich hätte mich erst mal selbst umschauen sollen, bevor ich Euch gebeten habe, mir etwas Rotes zu bringen.\n\nAlso wirklich.\n\n<Li Li wendet sich wieder den Zutaten zu, zerstampft die Blütenblätter und mischt dann etwas vom Blut dazu.>\n\n<Sie fängt an zu kichern.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29946] = { id = 29946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Baumutter", description = "Wir haben uns um die Alpha-Männchen gekümmert. Jetzt geht es an das Alpha-Weibchen.\n\nShed-Ling sind nicht besonders wählerisch, wenn es um die Fortpflanzung geht, aber oft gibt es eine dominante Mutterfigur. Die ist normalerweise größer, fieser und zäher als alle anderen.\n\nWisst Ihr, ich hätte nichts dagegen, meine Fähigkeiten bei einer Baumutter auf die Probe zu stellen. Kann ich gemeinsam mit Euch kämpfen?", sourceObjective = "Besiegt Chufa, die Zuckfußbaumutter.", completion = "Das sollte die Shed-Ling zumindest für ein paar Wochen in Schach halten. Genug Zeit für Trübtrunk, ungestört ein paar Bierchen zu brauen.\n\nUnd gehört das etwa nicht zu den wichtigen Dingen im Leben?", sourceObjectiveStatus = "unverified-source-field" }
quests[29947] = { id = 29947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der mit der Rübe tanzt", description = "Onkel Chen hat mich immer noch im Auge, das heißt, so bald komme ich nicht von hier weg. Es liegt wohl an Euch, diese Rüben - ich meine natürlich \"Karotten\" - zum Gewundenen Gewirr zu bringen und für mich abzuliefern.\n\nDas sollte nicht schwer sein. Werft einfach das Gemüse vor ein paar Shed-Ling und seht Euch ihre Reaktion an, wenn sie herausfinden, dass es sich in Wirklichkeit um eine Rübe handelt!", sourceObjective = "Werft orange angemalte Rüben vor 12 Zuckfußhamsterer.", completion = "Muahahahaaaa! Ich liebe es, Shed-Ling zu ärgern.", sourceObjectiveStatus = "unverified-source-field" }
quests[29948] = { id = 29948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebisch bis ins Mark", description = "Ihr und dieser Chen seid gute Leute, da Ihr mir gegen die Shed-Ling so helft. Ich bitte nicht gern um 'nen Gefallen, aber ich lehn' auch keinen ab.\n\nWenn Ihr dabei seid, diese Karnickel-Männer zu ärgern, könntet Ihr dann auch nach ein paar Hopfensäcken Ausschau halten? Bin mir ziemlich sicher, dass die letzte Nacht ein paar davon haben mitgehen lassen.\n\nBenutzen sie bestimmt als Kissen.", sourceObjective = "Holt 6 gestohlene Hopfensäcke aus dem Gewundenen Gewirr zurück.", progress = "Ich hab' genug davon, diesen Shed-Ling zu sagen, sie sollen sich von meinem Land fernhalten.", completion = "Ahhh, danke sehr, der Herr. Ihr seid ein wahrer Kavalier.", sourceObjectiveStatus = "unverified-source-field" }
quests[29949] = { id = 29949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erbe", description = "Ich würde sagen, wir haben uns unsere Belohnung verdient. Ich kann es kaum erwarten zu kosten, was Trübtrunk gebraut hat.", sourceObjective = "Trinkt gemeinsam mit Chen, Li Li und Trübtrunk.", completion = "Ich weiß, dass Onkel Chen zurückkommt. Ich mache mir keine Sorgen.\n\nDas ist vielleicht sogar meine große Chance, endlich Pandaria zu erkunden! Kein fetter Onkel mehr, der mir im Nacken sitzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[29950] = { id = 29950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Li Lis freier Tag", description = "Onkel Chen bat mich, mich während seiner Abwesenheit in keine Kämpfe verstricken zu lassen... Das heißt aber nicht, dass ich nicht auf Erkundungstour gehen kann. Endlich eine Gelegenheit, mich in Pandaria umzusehen, ohne alle 47 Schritte eine Pause zu machen!\n\nWollt Ihr mich begleiten? Ich wette, wir können viele tolle Orte aufsuchen, die nicht allzu weit weg sind.", sourceObjective = "Nehmt Li Li mit zu den Seidenfeldern, Neu-Cifera und zur Huangtzekaskade.", progress = "Seid Ihr bereit zu gehen?", completion = "Das war großartig! Wir beide sollten das unbedingt einmal wiederholen.\n\nUnd wie es scheint, sind wir noch vor Onkel Chen zurückgekehrt. Perfekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[29951] = { id = 29951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammiges Wasser", description = "Da Ihr gerade nichts besseres zu tun habt, kann ich Euch auch genauso gut mein Bierbrauverfahren vorstellen. Ist eigentlich kein großes \"Verfahren\"... Ich vermische einfach den ganzen Kram und warte.\n\nIhr habt sicherlich schon gehört, dass ich das schlammige Wasser vom Flussufer im Süden benutze. Würdet Ihr diese Phiole mit dem Wasser füllen und zurückbringen? Ich hole in der Zwischenzeit den Hopfen und die Gerste.", sourceObjective = "Füllt schlammiges Wasser in Trübtrunks Phiole.", progress = "Schon als ich Euch das erste Mal traf, wusste ich, Ihr seid zuverlässig.", completion = "Gut gemacht, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[29952] = { id = 29952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstörte Träume", description = "Ja, ich habe die Brauerei Sturmbräu gefunden... Allerdings erhielt ich dort nicht den warmen Empfang, den ich erwartet hätte.\n\n<Chen schenkt sich ein Bier ein.>\n\nWollt Ihr die Geschichte hören?", sourceObjective = "Sprecht mit Chen Sturmbräu und hört Euch seine Geschichte an.", completion = "Vielleicht war ich nicht dazu bestimmt, mich niederzulassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29966] = { id = 29966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles niederbrennen", description = "Seht, {name}!\n\nDie Hunde von der Allianz haben ein Lager auf dem Kamm errichtet.\n\nHier, nehmt meinen Grog. Lasst uns ein Feuer machen, das man noch in Sturmwind sehen kann!\n\nFür die Horde!", sourceObjective = "Nutzt Nazgrims Grog, um das Lager der Allianz am Idyllischen Aussichtspunkt zu zerstören.", completion = "Die Allianz muss aus diesem Land vertrieben werden, {name}!\n\nWir müssen Nägel mit Köpfen machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[29967] = { id = 29967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und das Dungamit macht Bumm!", description = "Das ist ein Notfall!\n\nAnscheinend habt Ihr durch das Auslöschen der Fischleute in ein Wespennest gestochen.\n\nSie führen einen Gegenangriff auf den Flotschhügel durch!\n\nIch hatte gehofft, noch mehr Zeit für die Forschung und Entwicklung zu haben, aber wir müssen meine Methangranatentheorie sofort auf die Probe stellen!\n\nWir treffen uns auf der Ostseite des Hügels. Wärmt Euren Wurfarm schon mal auf!", sourceObjective = "Sprecht mit Nieti Kuppelplopp östlich des Flotschhügels. Wehrt den Angriff der Jinyu mit seinen Methangranaten ab.", completion = "Ich würde sagen, der Angriff ist definitiv abgewehrt!", sourceObjectiveStatus = "unverified-source-field" }
quests[29968] = { id = 29968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grünliche Energie", description = "Ich sage nur eins: Methan!\n\nWir werden Umweltschützer. Saubere Verbrennung, gute Verfügbarkeit, ganz natürlich und hält mir die Druiden vom Leib, wenn wir wieder zurückkommen.\n\nAußerdem ist mir das Schießpulver ausgegangen...\n\nDaher brauche ich Eure Hilfe, {name}.\n\nNein, nein, die Drecksarbeit sollt Ihr nicht verrichten, ganz besonders nicht vor den Augen des Generals. Um diese 'Vorkommen' kümmere ich mich selbst.\n\nSammelt Ihr Holz für ein kleines Gebäude, denn ich plane schon einmal für einen längeren Zeitraum!", sourceObjective = "Sammelt 7 grüne Zweige in den Knatzelgründen.", progress = "Gebt Acht vor den feuchten… oje!", completion = "Ah, der Duft von Fortschritt und Methan.", sourceObjectiveStatus = "unverified-source-field" }
quests[29969] = { id = 29969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrochene Figur eines Irdenen", description = "Diese zerbrochene Figur wurde von ihrem ehemaligen Besitzer fortgeworfen. Mit den richtigen Materialien und Euren Fertigkeiten in der Juwelierskunst könntet Ihr sie jedoch vollständig reparieren.", sourceObjective = "Repariert die zerbrochene Figur mithilfe Eurer Fertigkeit und den richtigen Materialien.", sourceObjectiveStatus = "unverified-source-field" }
quests[29970] = { id = 29970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrochene Figur eines Irdenen", description = "Diese zerbrochene Figur wurde von ihrem ehemaligen Besitzer fortgeworfen. Mit den richtigen Materialien und Euren Fertigkeiten in der Juwelierskunst könntet Ihr sie jedoch vollständig reparieren.", sourceObjective = "Repariert die zerbrochene Figur mithilfe Eurer Fertigkeit und den richtigen Materialien.", sourceObjectiveStatus = "unverified-source-field" }
quests[29971] = { id = 29971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Spähers", description = "He, unsere Späher sind zurückgekehrt, als Ihr unterwegs wart. Und jetzt haltet Euch fest - sie haben irgendeinen Allianzbengel gefunden.\n\nIhr solltet vielleicht hingehen und sie eingehend befragen.", sourceObjective = "Sprecht mit Shokia auf dem Flotschhügel.", completion = "Wir haben vielleicht ein Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[29981] = { id = 29981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geflügelte Plagegeister", description = "Ich bin nicht von hier. Ich bin sogar vor dem heutigen Tage NOCH NIE hier gewesen. Aber selbst ich merke, dass hier etwas nicht stimmt.\n\nDie Mauer dort ist gebaut worden, um die Mantis aus dem Land der Pandaren fern zu halten. Und jetzt schicken sie ihre geflügelten Späher rüber und es ist, als ob es die Mauer gar nicht gäbe!\n\nDiese schwächlichen Späher überleben auch nur, weil sie Bauern und keine Soldaten angreifen. Gegen jemanden wie Euch hätten sie keine Chance.", sourceObjective = "Tötet 14 Mantis der Ik'thik in Steinpflug.", completion = "Lin hat Euch gebeten, uns zu helfen? Wie kommt sie darauf?\n\nAber sie hat Recht, wir sind zu wenig Leute. Wir nehmen Eure Hilfe und die des Mädchens gerne an. Ich danke Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29982] = { id = 29982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evakuierungsbefehl", description = "Ein paar Bauern sind noch draußen auf den Feldern... einige davon gefährlich nahe der zerbröselnden Mauer. Ich will nicht, dass sich Bauern als Helden aufführen. Wir kümmern uns um diesen Mantis-Schwarm und dann können sie nach Hause zurückkehren.\n\nMeine Shado-Pan sind zu beschäftigt mit der Verteidigung der Stadt, um die Evakuierung zu organisieren. Möchtet Ihr Euch vielleicht nützlich machen? Dann bringt diese Bauern außer Gefahr.", sourceObjective = "Evakuiert die Familien Schwarzgrund, Schaufelprank, Grünacker und Mergelpelz.", completion = "Ein paar sture Bauern wollen mir die Arbeit zusätzlich schwer machen?\n\n<Der Wachkommandant seufzt.>\n\nAuch gut. Ich werde keinem Pandaren das Recht verwehren, sein Land zu verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29983] = { id = 29983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verborgene Meister", description = "Von jetzt an sollten wir in der Lage sein, Steinpflug zu verteidigen.\n\n<Der Kommandant zeigt zu Lin Zartpfote.>\n\nLin hier sucht jemanden, den sie der \"verborgene Meister\" nennt. Ich glaube, ich weiß, von wem sie spricht und ich habe einen Hinweis für Euch.\n\nGeht nach Norden.", sourceObjective = "Sucht Meister Schrammtatz im Tal der Vier Winde.", completion = "Ihr wollt ausgebildet werden?\n\n<Der Pandaren mustert Euch einige Sekunden lang, ohne etwas zu sagen.>\n\nIn Ordnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[29984] = { id = 29984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit eiserner Faust: Herausforderung des Bambus", description = "Wir werden Euch jetzt einer Prüfung unterziehen - der Herausforderung des Bambus.\n\nEure Freundin Lin hat diese Prüfung nicht bestanden.\n\nFolgt mir und hört mir aufmerksam zu.", sourceObjective = "Sprecht mit Meister Schrammtatz und versucht dann, den Stapel Bambusstangen dreimal zu treffen.", progress = "Wenn Ihr diese Prüfung nicht besteht, gibt es vermutlich keinen Grund mehr, Eure Ausbildung fortzusetzen.", completion = "Ihr habt Talent, {name}. Wir werden fortfahren.\n\nUnd jetzt ist es Zeit für die erste Einheit Eurer Ausbildung.", sourceObjectiveStatus = "unverified-source-field" }
quests[29985] = { id = 29985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inkarnationen im Nebel", description = "Der Nebel in diesem Wald und die seltsamen Kreaturen darin sind ein ständiges Ärgernis - und darum überlasse ich diese Angelegenheit gerne Schülern wie Euch. Die Kreaturen, die sich im Nebel verbergen, müssen unaufhörlich bekämpft werden.\n\nBetrachtet es als Teil Eurer Ausbildung.", sourceObjective = "Tötet 12 Nebelinkarnationen.", completion = "Ihr habt meine Anweisungen genauestens befolgt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29986] = { id = 29986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nebelwarten", description = "<Schüler/Schülerin>.\n\nWir sind von einigen Warten umgeben, die in der Nähe meines Zuhauses im Wald versteckt sind. Sie können recht effizient den Nebel auflösen, müssen aber fortwährend gewartet werden.\n\nIhr findet eine im Norden, eine im Westen und eine im Süden. Findet diese Warten und entzündet sie.", sourceObjective = "Entzündet die nördliche Nebelwarte, die westliche Nebelwarte und die südliche Nebelwarte.", completion = "Ihr gereicht Eurem Volk zur Ehre, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29987] = { id = 29987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit eiserner Faust: Herausforderung des Holzes", description = "Ihr seid gut vorangekommen mit Eurer Ausbildung. Folgt mir. Ich möchte, dass Ihr Euch der Herausforderung des Holzes stellt.", sourceObjective = "Sprecht mit Meister Schrammtatz und versucht dann, den Stapel Holzbretter viermal zu treffen.", progress = "Ich bin bereit, {name}. Und Ihr?", completion = "Ihr verfügt über die Gabe der Konzentration, {name}. Nicht viele meiner Schüler kommen so weit.", sourceObjectiveStatus = "unverified-source-field" }
quests[29988] = { id = 29988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Vorliebe für Eier", description = "Ich spüre Eure Ungeduld, aber Ihr seid noch nicht so weit. Vor der letzten Prüfung warten noch weitere Ausbildungsteile auf Euch. Und jetzt zu Eurer Aufgabe... Ich möchte, dass Ihr einige Eier für mich sammelt.\n\nJawohl, Eier. Im Marschgebiet oben auf den Bergen im Osten leben viele Vögel, die allesamt sehr friedfertig sind. Ihr solltet keine Probleme haben, mir genug Eier für einige Wochen zu bringen.", sourceObjective = "Sammelt 10 Eier von Kaiserschwalben, 4 Eier von Weißkopfkranichen und 1 Ei eines Hornschnabelschreiters.", progress = "Wie läuft denn die Eierjagd?", completion = "Jetzt wisst Ihr, warum ich die Eier nicht selber sammeln mag.\n\nSollen wir mit der Ausbildung fortfahren?", sourceObjectiveStatus = "unverified-source-field" }
quests[29989] = { id = 29989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit eiserner Faust: Herausforderung des Steins", description = "In der kurzen Zeit Eures Aufenthaltes habt Ihr schon viel erreicht, {name}. Normalerweise würde ich Euch nicht so früh dieser Prüfung unterziehen... Aber ich habe das Gefühl, dass Ihr dazu bereit seid.\n\nEs ist Zeit für die Herausforderung des Steins.", sourceObjective = "Sprecht mit Meister Schrammtatz und versucht dann, den Stapel Steinblöcke fünfmal zu treffen.", completion = "<Meister Schrammtatz verbeugt sich vor Euch.>\n\nIhr vermögt den Stein erbeben und unter Eurer Faust zerbrechen zu lassen. Ihr verfügt über die mentale Stärke, Berge zu versetzen.\n\nEs gibt nichts mehr, was ich Euch noch lehren könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[29990] = { id = 29990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung und Disziplin", description = "Ich habe mir gesagt, dass, falls ich es jemals hierher zum verborgenen Meister schaffen würde, ich so viel wie möglich von ihm lernen werde. Das ist meine Chance, {name}. Die lasse ich mir nicht entgehen.\n\nAllerdings fürchte ich, dass Steinpflug uns braucht. Ich bin früh weggegangen, bevor wir die Mantis-Späher zurückdrängen konnten. Ich hätte ein besseres Gefühl, wenn Ihr Euch für mich beim Wachkommandanten melden könntet.\n\nOh, und falls Ihr auf die anderen stoßt, solltet Ihr ihnen vielleicht sagen, wo sich der verborgene Meister befindet...", sourceObjective = "Meldet Euch bei Wachkommandant Lun Mai bei Steinpflug im Tal der Vier Winde.", completion = "Ich freue mich zu hören, dass es Lin gut geht.\n\nUnsere Verteidigungslinien halten fürs Erste. Die Mantis schicken weiterhin ihre Späher über die Mauer, aber viel weiter sind sie noch nicht gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29992] = { id = 29992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nomen est omen", description = "Ich würde gerne Xiao, Kang und den anderen sagen, dass ich den verborgenen Meister gefunden habe, aber jetzt lässt er mich nicht gehen! Er sagt, ich müsse zuerst die Herausforderung des Bambus bestehen.\n\n<Lin flüstert:> Wisst Ihr, wie man das macht?\n\nWie es aussieht, sitze ich hier erst einmal fest und muss mich darin üben, gegen diesen Stein zu boxen. Meine Knöchel halten das nicht mehr lange durch.\n\nWenn Ihr mir ein paar Jademondblätter bringen könntet, könnte ich eine Salbe zubereiten, die meine Schmerzen zumindest teilweise lindert.", sourceObjective = "Sammelt 18 Jademondblätter.", progress = "Au! Au! Au!", completion = "<Lin macht eine kurze Pause, um die Blätter über ihre geschwollenen Knöchel zu reiben.>\n\nHabt Dank! Das reicht fürs Erste - eine richtige Salbe kann ich dann später zubereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29993] = { id = 29993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet den Jungen", description = "Habt Ihr meinen Sohn Lo gesehen? Eben war er noch hier und ich sagte ihm, dass wir heute aufbrechen.\n\nEr ist gewiss losgezogen, um diese junge Syra Zapfgold zu beeindrucken. Das ist auch der Grund, warum wir gehen müssen!\n\nMein Sohn wird nicht mit einer Zapfgold davonlaufen!\n\nIch werde mich hier nach ihnen umsehen.\n\nIch habe sie schon ein paar Mal dabei erwischt, wie sie sich zum Arboretum geschlichen haben. Könntet Ihr dort vielleicht nach ihnen schauen?", sourceObjective = "Sprecht mit Tintenmeister Wei.", completion = "Ihr sucht zwei Liebende, die sich den Wünschen ihrer Familien nicht beugen wollen. Sie waren hier und suchten einen Weg für sich.\n\nLeider konnten sie unter unseren Bäumen und Kunstwerken keine Antwort finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[29995] = { id = 29995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrein der Morgensonne", description = "Die \"Kinder\", die Ihr sucht, sind eigentlich gar keine Kinder, sondern erwachsene Pandaren, auch wenn ihre Ältesten etwas anderes behaupten. Ihre Liebe kommt der Fehde zwischen ihren Familien in die Quere.\n\nIhr könnt sowohl Syra als auch Lo am Schrein der Morgensonne antreffen, wo sie bei den einstigen Pandriarchen nach einer Lösung für ihr Dilemma suchen.", sourceObjective = "Sucht am Schrein der Morgensonne nach Syra Zapfgold.", completion = "Oh! Bitte sagt mir, dass Ihr uns helfen könnt. Sie haben meinem Lo sehr wehgetan.", sourceObjectiveStatus = "unverified-source-field" }
quests[29997] = { id = 29997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Dilemma des Sehers", description = "Da Ihr uns bei den Minen sehr geholfen habt, wärt Ihr vielleicht auch bereit, uns hier am Tempel bei einem kleinen Problem zu unterstützen?\n\nDer weise Mari hat sich vor Kurzem beschwert.\n\nDie Wasserelementare sind neuerdings sehr verspielt und haben sich seinen Zeremonienstab angeeignet.\n\nIch wäre Euch sehr dankbar, wenn Ihr ihm helfen könntet. Vielleicht lege ich sogar ein Wort bei der Jadeschlange für Euch ein.\n\nFolgt einfach dem Weg gen Norden.", sourceObjective = "Vernichtet Wasserteufel, um den Stab des weisen Mari zurückzubekommen.", progress = "Die Teiche sind umwölkt. Ich brauche meinen Stab, um die Geister zu beruhigen und mit dem Wasser zu sprechen.", completion = "Ich bin nur ein alter Jinyu und kann diese lästigen Wassergeister nicht fangen. Vielen Dank, {name}, dass Ihr mir meinen Stab zurückgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
